String addCRLF(const String& str) {
  String result = str;
  if (result.length() < 2 || result.substring(result.length() - 2) != "\r\n") {
    if (result.substring(result.length() - 1) == "\n") {
        result.replace("\n", "\r\n");
    } else {
        result.concat("\r\n");
    }
  }
  return result;
}

// Crafted with standard coding tools Jan 28, 2023
bool searchForFile(fs::FS &fs, const char* fileName) {
    File root = fs.open("/");
    File file = root.openNextFile();
    while (file) {
        if (strcmp(file.name(), fileName) == 0) {
            Serial.print("Found file: ");
            Serial.println(file.name());
            file.close();
            return true;
        }
        file = root.openNextFile();
    }

    Serial.println("File not found");
    return false;
}

String listDir(fs::FS &fs, const char * dirname, uint8_t levels){
    File root = fs.open(dirname);
    if (!root){
        Serial.println("Failed to open directory");
        return ("None");
    }
    if (!root.isDirectory()){
        Serial.println("Not a directory");
        return ("None");
    }
    String fileList;
    File file = root.openNextFile();
    while (file){
        if (file.isDirectory()){
            if (levels){listDir(fs, file.name(), levels - 1);}
        } else {
            fileList += file.name();
            fileList += ",";
        }
        file = root.openNextFile();
    }
    if (fileList == ""){
        return ("No Logs");
    } else {
        return (fileList);
    }
}

String getFile(fs::FS &fs, String filePath) {
    File file = fs.open(filePath);
    String s;
    if (!file){
        Serial.println("Failed to open file for reading");
        return("null");
    }
    if (file.available() && (file.size() < 100000)){
        s = (file.readString());
        file.close();
        return(s);
    } else {
        return("null");
    }
}

bool appendFile(fs::FS &fs, const char * path, const char * message, bool ensureCRLF){
    File file = fs.open(path, FILE_APPEND);
    const char * toSend;
    if (!file){
        Serial.println("Failed to open file for appending");
        return (false);
    }

    if (ensureCRLF)
    {
        toSend = addCRLF(message).c_str();
    } else {
        toSend = message;
    }

    if (file.print(toSend)){
    } else {
        Serial.println("Append failed");
        return (false);
    }
    file.close();
    return (true);
}

bool writeFile(fs::FS &fs, const char * path, const char * message, bool newLine){
    File file = fs.open(path, FILE_WRITE);
    if(!file){
        Serial.println("Failed to open file for writing");
        return(false);
    }
    if(file.print(message)){
        if (newLine){file.print("\r\n");}
    } else {
        Serial.println("Write failed");
        return(false);
    }
    file.close();
    return(true);
}

bool deleteFile(fs::FS &fs, const char * path){
    File root = fs.open(path);
    if(!root){
        Serial.println("Failed to open file/directory");
        return(false);
    }
    if(root.isDirectory()){
        File file = root.openNextFile();
        file = root.openNextFile();
        while (file) 
        {
            String fileName = "/";
            fileName += file.name();
            if (!fs.remove(fileName)) {
                return(false);
            }
            file = root.openNextFile();
        }
        return(true);
    } else {
        return(fs.remove(path));
    }
}

bool sdSetup(){
    const uint8_t SCK = 18;
    const uint8_t MISO = 19;
    const uint8_t MOSI = 23;
    const uint8_t CS = 5;

    spi.begin(SCK, MISO, MOSI, CS);

    if (!SD.begin(CS,spi,8000000)) {
        Serial.println("Card Mount Failed");
        return(false);
    }

    uint8_t cardType = SD.cardType();

    if(cardType == CARD_NONE){
        Serial.println("No SD card attached");
        return(false);
    }
    Serial.println("SD Card Initialized");
    return(true);
}

#include <iostream>
#include <vector>
#include <map>
#include <stack>
#include <queue>
using namespace std;

class Graph
{
    vector<int> *vertex;
    int s;

public:
    Graph(int SIZE = 6)
    {
        this->s = SIZE;
        this->vertex = new vector<int>[SIZE];
    }
    void AddEdge(int u, int v)
    {
        if (u >= s || v >= s)
        {
            cout << "vertex index not defined!" << endl;
            return;
        }
        vertex[u].push_back(v);
        vertex[v].push_back(u);
    }
    void PrintGraph()
    {
        cout << " ---------  Graph  --------- " << endl;
        for (int i = 0; i < vertex->size(); i++)
        {
            cout << i << " -> ";
            for (int j = 0; j < vertex[i].size(); j++)
            {
                cout << vertex[i][j] << " | ";
            }
            cout << endl;
        }
        cout << endl;
    }
    void RemoveEdge(int u, int v)
    {
        for (int i = 0; i < vertex[u].size(); i++)
        {
            if (vertex[u][i] == v)
            {
                vertex[u].erase(vertex[u].begin() + i);
            }
        }
        for (int i = 0; i < vertex[v].size(); i++)
        {
            if (vertex[v][i] == u)
            {
                vertex[v].erase(vertex[v].begin() + i);
            }
        }
    }
    void BFS(int source)
    {
        vector<bool> visited(vertex->size(), false);
        queue<int> q;
        visited[source] = true;
        q.push(source);
        while (!q.empty())
        {
            source = q.front();
            q.pop();
            cout << source << " -> ";
            for (auto e : vertex[source])
            {
                if (visited[e] == false)
                {
                    visited[e] = true;
                    q.push(e);
                }
            }
        }
        cout << endl;
    }
};

int main(int argc, char const *argv[])
{
    Graph g(6);
    g.AddEdge(1, 2);
    g.AddEdge(2, 3);
    g.AddEdge(1, 4);
    g.AddEdge(1, 0);
    g.AddEdge(4, 5);
    g.AddEdge(5, 3);
    g.AddEdge(5, 1);
    g.AddEdge(5, 0);
    g.AddEdge(1, 1);
    g.BFS(0);

    return 0;
}

