static inline ll power(ll a, ll b, ll p) {
	ll result = 1;
	for(; b > 0; b >>= 1, a = a * a % p) {
		if(b & 1) {
			result = result * a % p;
		}
	}
	return result;
}
static inline ll inverse(ll a, ll p) {
	return power(a, p - 2, p);
}

