class Graph {
    public:
    int V = 0;
    int E = 0;
    vector<vector<int>> graph;
    Graph(int v, int e) {
        V = v + 1;
        E = e;
        graph.resize(V, vector<int>());
    }

    void add_edge(int a, int b) {
        graph[a].push_back(b);
    }

    bool bfs(int start, int end) {
        vector<bool> visited(V, false);
        visited[start] = true;
        queue<int> q;
        q.push(start);
        while (!q.empty() && !visited[end]) {
            start = q.front();
            q.pop();
            for(int i: graph[start]) {
                if(!visited[i]) {
                    visited[i] = true;
                    q.push(i);
                }
            }
        }
        return visited[end];
    }

    void recurse(int start, vector<bool>& visited, int end) {
        if(start == end) {
            visited[start] = true;
            return;
        }
        visited[start] = true;
        for(int i: graph[start]) {
            if(!visited[i]) {
                recurse(i, visited, end);
            }
        }
    }

    bool dfs(int start, int end) {
        vector<bool> visited(V, false);
        recurse(start, visited, end);
        return visited[end];
    }
};

// NextGreater, NextSmaller at Right, Left

vector<int> next_greater_in_right(vector<int> a, int n) {
    vector<int> right_index(n, n);
    stack<int> st;
    for(int i = 0; i < n; i++) {
        while(!st.empty() && a[i] > a[st.top()]) {
            right_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return right_index;
}

vector<int> next_greater_in_left(vector<int>& a, int n) {
    vector<int> left_index(n, -1);
    stack<int> st;
    for(int i = n - 1; i >= 0; i--) {
        while(!st.empty() && a[i] > a[st.top()]) {
            left_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return left_index;
}

vector<int> next_smaller_in_right(vector<int>& a, int n) {
    vector<int> right_index(n, n);
    stack<int> st;
    for(int i = 0; i < n; i++) {
        while(!st.empty() && a[i] < a[st.top()]) {
            right_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return right_index;
}

vector<int> next_smaller_in_left(vector<int>& a, int n) {
    vector<int> left_index(n, -1);
    stack<int> st;
    for(int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[i] < a[st.top()]) {
            left_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return left_index;
}

