using namespace std;

int n, k, a[100100];
bool b[100100];
void init()
{
    cin >> n >> k;
    for (int i = 0; i < k; i++)
    {
        cin >> a[i];
        b[a[i]] = 1;
    }
}
void pre()
{
    for (int i = k - 1; i >= 0; i--)
    {
        if (a[i] > 1 && !b[a[i] - 1])
        {
            b[a[i]] = 0;
            a[i] = a[i] - 1;
            b[a[i]] = 1;
            break;
        }
        if (a[i] < n && !b[a[i] + 1])
        {
            b[a[i]] = 0;
            a[i] = a[i] + 1;
            b[a[i]] = 1;
            break;
        }
    }
    for (int i = 0; i < k; i++)
        cout << a[i] << " ";
    cout << endl;
}
void nxt()
{
    for (int i = 0; i < k; i++)
    {
        if (a[i] > 1 && !b[a[i] - 1])
        {
            b[a[i]] = 0;
            a[i] = a[i] - 1;
            b[a[i]] = 1;
            break;
        }
        if (a[i] < n && !b[a[i] + 1])
        {
            b[a[i]] = 0;
            a[i] = a[i] + 1;
            b[a[i]] = 1;
            break;
        }
    }
    for (int i = 0; i < k; i++)
        cout << a[i] << " ";
    cout << endl;
}
