}

/*!
 *  @brief  Clears interrupt
 */
void Adafruit_APDS9960::clearInterrupt() {
  this->write(APDS9960_AICLEAR, NULL, 0);
}
/*!
 *  @brief  Sets interrupt limits
 *  @param  low
 *          Low limit
 *  @param  high
 *          High limit
 */
void Adafruit_APDS9960::setIntLimits(uint16_t low, uint16_t high) {
  write8(APDS9960_AILTIL, low & 0xFF);
  write8(APDS9960_AILTH, low >> 8);
  write8(APDS9960_AIHTL, high & 0xFF);
  write8(APDS9960_AIHTH, high >> 8);
}

/*!
 *  @brief  Writes specified value to given register
 *  @param  reg
 *          Register to write to
 *  @param  value
 *          Value to write
 */
void Adafruit_APDS9960::write8(byte reg, byte value) {
  this->write(reg, &value, 1);
}

/*!
 *  @brief  Reads 8 bits from specified register
 *  @param  reg
 *          Register to write to
 *  @return Value in register
 */
uint8_t Adafruit_APDS9960::read8(byte reg) {
  uint8_t ret;
  this->read(reg, &ret, 1);

  return ret;
}

/*!
 *  @brief  Reads 32 bits from specified register
 *  @param  reg
 *          Register to write to
 *  @return Value in register
 */
uint32_t Adafruit_APDS9960::read32(uint8_t reg) {
  uint8_t ret[4];
  uint32_t ret32;
  this->read(reg, ret, 4);
  ret32 = ret[3];
  ret32 |= (uint32_t)ret[2] << 8;
  ret32 |= (uint32_t)ret[1] << 16;
  ret32 |= (uint32_t)ret[0] << 24;
  return ret32;
}

/*!
 *  @brief  Reads 16 bites from specified register
 *  @param  reg
 *          Register to write to
 *  @return Value in register
 */
uint16_t Adafruit_APDS9960::read16(uint8_t reg) {
  uint8_t ret[2];
  this->read(reg, ret, 2);

  return (ret[0] << 8) | ret[1];
}

/*!
 *  @brief  Reads 16 bites from specified register
 *  @param  reg
 *          Register to write to
 *  @return Value in register
 */
uint16_t Adafruit_APDS9960::read16R(uint8_t reg) {
  uint8_t ret[2];
  this->read(reg, ret, 2);

  return (ret[1] << 8) | ret[0];
}

/*!
 *  @brief  Reads num bytes from specified register into a given buffer
 *  @param  reg
 *          Register
 *  @param  *buf
 *          Buffer
 *  @param  num
 *          Number of bytes
 *  @return Position after reading
 */
//  uint8_t Adafruit_APDS9960::read(uint8_t reg, uint8_t *buf, uint8_t num) {
//   buf[0] = reg;
//   i2c_dev->write_then_read(buf, 1, buf, num);
//   return num;
// }
 // Designed via basic programming aids since no 'read then write function' in the Bela I2c class
uint8_t Adafruit_APDS9960::read(uint8_t reg, uint8_t *buf, uint8_t num) {
    // First, write the register address we want to read from
    if(i2c.writeBytes(&reg, 1) <= 0) {
        fprintf(stderr, "Failed to write to the I2C device\n");
        return 0;
    }

    // Then, read the specified number of bytes from that register into the buffer
    if(i2c.readBytes(buf, num) <= 0) {
        fprintf(stderr, "Failed to read from the I2C device\n");
        return 0;
    }

    return num;
}

/*!
 *  @brief  Writes num bytes from specified buffer into a given register
 *  @param  reg
 *          Register
 *  @param  *buf
 *          Buffer
 *  @param  num
 *          Number of bytes
 */
// void Adafruit_APDS9960::write(uint8_t reg, uint8_t *buf, uint8_t num) {
//   uint8_t prefix[1] = {reg};
//   i2c_dev->write(buf, num, true, prefix, 1);
// }
void Adafruit_APDS9960::write(uint8_t reg, uint8_t *buf, uint8_t num) {
    // First, write the register address we want to write to
    if(i2c.writeBytes(&reg, 1) <= 0) {
        fprintf(stderr, "Failed to write to the I2C device\n");
        return;
    }

    // Then, write the data
    if(i2c.writeBytes(buf, num) <= 0) {
        fprintf(stderr, "Failed to write to the I2C device\n");
    }
}

#include <bits/stdc++.h>

using namespace std;


typedef long long ll;
typedef vector<ll> vi;
typedef pair<ll, ll> ii;
typedef vector<ii> vii;

// ref: https://stackoverflow.com/questions/23556249/continued-fractions
ii contToFrac(vi a, int size) {
    ll n = 1;
    ll d = a[size - 1];
    for (int i = size - 2; i >= 0; i--) {
        int nextd = d * a[i] + n;
        n = d;
        d = nextd;
    }
    return ii(d, n);
}

vi fracToCont(ii frac) {
    vi a;
    ll n = frac.first;
    ll d = frac.second;
    while (d != 0) { // d = 0 means n is divisible by d
        a.push_back(n / d);
        n = n % d;
        swap(n, d);
    }
    return a;
}

ii fracAdd(ii a, ii b) {
    return ii(a.first * b.second + a.second * b.first, a.second * b.second);
}

ii fracSubtract(ii a, ii b) {
    return ii(a.first * b.second - a.second * b.first, a.second * b.second);
}

ii fracMultiply(ii a, ii b) {
    return ii(a.first * b.first, a.second * b.second);
}

ii fracDivide(ii a, ii b) {
    return ii(a.first * b.second, a.second * b.first);
}

void changeFracToContAndPrint(ii frac) {
    vi a = fracToCont(frac);
    while (a.size() > 1 && a.back() == 0) a.pop_back();
    for (int i = 0; i < a.size(); i++) {
        if (i < a.size() - 1) cout << a[i] << " ";
        else cout << a[i] << '\n';
    }
}

// NOTE ABOVE typedef i lazily replaced int into long long...

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    //freopen("error.txt", "w", stderr);

    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n1, n2;
    cin >> n1 >> n2;
    vi a(n1), b(n2);
    for (int i = 0; i < n1; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n2; i++) {
        cin >> b[i];
    }
    ii frac1 = contToFrac(a, n1);
    ii frac2 = contToFrac(b, n2);
    // add
    ii frac = fracAdd(frac1, frac2);
    changeFracToContAndPrint(frac);
    // subtract
    frac = fracSubtract(frac1, frac2);
    changeFracToContAndPrint(frac);
    // multiply
    frac = fracMultiply(frac1, frac2);
    changeFracToContAndPrint(frac);
    // divide
    frac = fracDivide(frac1, frac2);
    changeFracToContAndPrint(frac);

    cerr << "time taken : " << (float) clock() / CLOCKS_PER_SEC << " secs" << '\n';
    return 0;
}


