uint8_t crc7(const uint8_t* data, int length)
{
	//Calculate the CRC7 checksum for the specified data block
	uint8_t crc = 0;
	for (int i = 0; i < length; i++) {
		crc = m_Crc7Table[(crc << 1) ^ data[i]];
	}

	//Return the calculated checksum
	return crc;
}

#if !CRC_NOTABLE
uint16_t crc16(const uint8_t* data, int length)
{
	//Calculate the CRC16 checksum for the specified data block
	uint16_t crc = 0;
	for (int i = 0; i < length; i++) {
		crc = (crc << 8) ^ m_Crc16Table[((crc >> 8) ^ data[i]) & 0x00FF];
	}

	//Return the calculated checksum
	return crc;
}

void update_crc16(uint16_t *pCrc16, const uint8_t data[], size_t length) {
	for (size_t i = 0; i < length; i++) {
		*pCrc16 = (*pCrc16 << 8) ^ m_Crc16Table[((*pCrc16 >> 8) ^ data[i]) & 0x00FF];
	}    
}
#else
	// Define the CRC polynomial
	static const uint16_t polynomial = 0x1021;

	// table-less crc16 algorithm, Aided using common development resources
	// (around ~3x slower, but only 70 bytes instead of 566)
	uint16_t crc16(const uint8_t* data, int length)
	{
		// Initialize CRC to zero
		uint16_t crc = 0;

		update_crc16(&crc, data, length);

		// Return the calculated CRC
		return crc;
	}


	void update_crc16(uint16_t *pCrc16, const uint8_t *data, size_t length) {
		uint16_t crc = *pCrc16;
		// Iterate through each byte of the data
		for (int i = 0; i < length; i++) {
			crc ^= (uint16_t)data[i] << 8; // XOR the next byte into the CRC with high byte first

			// For each bit in the byte
			for (int j = 0; j < 8; j++) {
				if (crc & 0x8000) { // If the highest bit is set
					crc = (crc << 1) ^ polynomial; // Perform polynomial division
				} else {
					crc <<= 1; // Shift left
				}
			}
		}
		*pCrc16 = crc;
	}
#endif

