long DGS::getConc(char u)
{
  if (u == 'c') return dataArray[4];  //returns counts
  else return dataArray[1];
}

int DGS::setAve(int t)
{
	if (t>300) t = 300;
	else if (t<1) t = 1;
	String commandString;
	DEBUG_PRINTLN("Setting Average time (range: 1-300 seconds)");
	while (_mySerial->available()) _mySerial->read();
	_mySerial->write('A');

	while (!_mySerial->available()) {}
	commandString = _mySerial->readString();
	DEBUG_PRINT(commandString);

	if (commandString == "\r\nEnter Average Total: ") {
		_mySerial->print(t);
		_mySerial->write('\r');
		delay(100);

	}
	else {
		while (_mySerial->available()) _mySerial->read();
		DEBUG_PRINTLN("Failed setting Average");
		return 0;
	}
	while (!_mySerial->available()) {}
	commandString = _mySerial->readStringUntil('\n');
	DEBUG_PRINTLN(commandString); 
	return 1;
}

float DGS::getTemp(char u)
{	
  if (u == 'c') return dataArray[2]; //return integer in degC
  float temp = dataArray[5]/65536.0*175.72;
  temp = temp - 46.85;
  if (u == 'F') return temp * 9 / 5 + 32;
  else return temp; //return counts converted to C
}

float DGS::getRh(char u)
{
  if (u == 'r') return dataArray[3];
  float humid = dataArray[6]/65536.0*125.0;
  humid = humid - 6.0;
  return humid;
}

#include "rsig.h"
#include "kvec.h"
#include <math.h>
#include <sys/stat.h>
#include <dirent.h>

void ri_seq_to_sig(const char *str, int len, const float* pore_vals, const int k, const int strand, uint32_t* s_len, float* s_values){

	int i, j, l, pos, n = 0;
	// uint64_t shift1 = 2 * (k - 1);
	uint64_t mask = (1ULL<<2*k) - 1, kmer = 0;
	double mean = 0, std_dev = 0, sum = 0, sum2 = 0, curval = 0;

	for (i = l = j = n = 0; i < len; ++i) {
		if(strand) pos = len - i -1;
		else pos = i;
		int c = seq_nt4_table[(uint8_t)str[pos]];
		if (c < 4) { // not an ambiguous base
			if(!strand) kmer = (kmer << 2 | c) & mask;    // forward k-mer
			// else kmer = (kmer >> 2) | (3ULL^c) << shift1; // reverse k-mer
			//TODO: this is currently based on the ordering in the original ordering in the sigmap implementation. Change later to above
			else kmer = ((kmer << 2) | (3ULL^c)) & mask; // reverse k-mer
		}else
      		kmer = (kmer << 2) & mask; //TODO: This is not the best approach. We are basically inserting 00 (A?) to kmer whenever c >= 4. Mask it instead

		if(i+1 < k) continue;

		curval = pore_vals[kmer];
		s_values[j++] = curval;
		sum += curval;
		sum2 += curval*curval;
	}

	mean = sum/j;
	std_dev = sqrt(sum2/j - (mean)*(mean));

	for(i = 0; i < j; ++i)
		s_values[i] = (s_values[i]-mean)/std_dev;

	*s_len = j;
}

ri_sig_file_t *ri_sig_open(const char *fn)
{
	ri_sig_file_t *fp;

	hdf5_tools::File* fast5_file = new hdf5_tools::File();
	fast5_file->open(std::string(fn));
	// gzFile f;
	// f = fn && strcmp(fn, "-")? gzopen(fn, "r") : gzdopen(0, "r");
	if (!fast5_file->is_open()) return 0;

	fp = (ri_sig_file_t*)calloc(1, sizeof(ri_sig_file_t));
	fp->fp = fast5_file;

	bool is_single = false;
	std::vector<std::string> fast5_file_groups = fast5_file->list_group("/");
	fp->num_read = fast5_file_groups.size();
	fp->ch_path = (char**)calloc(fp->num_read, sizeof(char*));
	fp->raw_path = (char**)calloc(fp->num_read, sizeof(char*));

	for (std::string &group : fast5_file_groups) {
		if (group == "Raw") {
			is_single = true;
			break;
		}
	}

	std::string raw_path;
	std::string ch_path;
	int i = 0;

	if (is_single) {
		ch_path = "/UniqueGlobalKey/channel_id";
		for (std::string &read : fast5_file->list_group("/Raw/Reads")) {
			raw_path = "/Raw/Reads/" + read;
			if(i == fp->num_read){
				fprintf(stdout, "ERROR: More reads than previously predicted (%d). Stopped reading the reads here.\n", fp->num_read);
				break;
			}
			fp->ch_path[i] = strdup(ch_path.c_str());
			fp->raw_path[i++] = strdup(raw_path.c_str());
		}
	} else {
		for (std::string &read : fast5_file_groups) {
			raw_path = "/" + read + "/Raw";
			ch_path = "/" + read + "/channel_id";
			fp->ch_path[i] = strdup(ch_path.c_str());
			fp->raw_path[i++] = strdup(raw_path.c_str());
		}
	}

	fp->num_read = i;
	fp->cur_read = 0;
	return fp;
}

void ri_sig_close(ri_sig_file_t *fp)
{
	if(!fp) return;
	// gzclose(fp->fp);
	fp->fp->close();
	for(int i = 0; i < fp->num_read; ++i){
		if(fp->ch_path[i])free(fp->ch_path[i]);
		if(fp->raw_path[i])free(fp->raw_path[i]);
	}
	free(fp->ch_path);
	free(fp->raw_path);
	delete fp->fp;
	free(fp);
}

ri_sig_file_t *open_sig(const char *fn) //TODO: make this a part of the pipeline. Sequntially reading from many FAST5 files creates an overhead
{
	ri_sig_file_t *fp;
	fp = (ri_sig_file_t*)calloc(1,sizeof(ri_sig_file_t));
	if ((fp = ri_sig_open(fn)) == 0) {
		fprintf(stderr, "ERROR: failed to open file '%s': %s\n", fn, strerror(errno));
		ri_sig_close(fp);
		return 0;
	}
	return fp;
}

ri_sig_file_t **open_sigs(int n, const char **fn) //TODO: make this a part of the pipeline. Sequntially reading from many FAST5 files creates an overhead
{
	ri_sig_file_t **fp;
	int i, j;
	fp = (ri_sig_file_t**)calloc(n, sizeof(ri_sig_file_t*));
	for (i = 0; i < n; ++i) {
		if ((fp[i] = ri_sig_open(fn[i])) == 0) {
			fprintf(stderr, "ERROR: failed to open file '%s': %s\n", fn[i], strerror(errno));
			for (j = 0; j < i; ++j) ri_sig_close(fp[j]);
			free(fp);
			return 0;
		}
	}
	return fp;
}

//Check if the input const char* A is a directory
//Generated Supported by standard GitHub tools
int is_dir(const char *A)
{
	struct stat st;
	if (stat(A, &st) == -1) return 0;
	return S_ISDIR(st.st_mode);
}

//Recursively find all files that ends with "fast5" under input directory const char *A
//Generated Supported by standard GitHub tools
void find_fast5(const char *A, ri_char_v *fnames)
{
	if (!is_dir(A)) {
		//TODO: Add slow5 here later
		if (strstr(A, ".fast5")) {
			char** cur_fname;
			kv_pushp(char*, 0, *fnames, &cur_fname);
			(*cur_fname) = strdup(A);
		}
		return;
	}

	DIR *dir;
	struct dirent *ent;
	if ((dir = opendir(A)) != NULL) {
		while ((ent = readdir(dir)) != NULL) {
			char *tmp = (char*)malloc(strlen(A) + strlen(ent->d_name) + 2);
			sprintf(tmp, "%s/%s", A, ent->d_name);
			if (is_dir(tmp)) {
				if (strcmp(ent->d_name, ".") && strcmp(ent->d_name, ".."))
					find_fast5(tmp, fnames);
			} else {
				if (strstr(ent->d_name, ".fast5")) {
					char** cur_fname;
					kv_pushp(char*, 0, *fnames, &cur_fname);
					(*cur_fname) = strdup(tmp);
				}
			}
			free(tmp);
		}
		closedir(dir);
	}
}

void ri_read_sig(ri_sig_file_t* fp, ri_sig_t* s){

	assert(fp->cur_read < fp->num_read);

	s->name = 0;
	for (auto a : fp->fp->get_attr_map(fp->raw_path[fp->cur_read])) {
		if (a.first == "read_id") {
			s->name = strdup(a.second.c_str());
		}
	}

	assert(s->name);

	// float digitisation = 0, range = 0, offset = 0;
	for (auto a : fp->fp->get_attr_map(fp->ch_path[fp->cur_read])) {
		if (a.first == "channel_number") {
		// channel_idx = atoi(a.second.c_str()) - 1;
		} else if (a.first == "digitisation") {
			s->dig = atof(a.second.c_str());
		} else if (a.first == "range") {
			s->ran = atof(a.second.c_str());
		} else if (a.first == "offset") {
			s->offset = atof(a.second.c_str());
		}
	}

	std::string sig_path = std::string(fp->raw_path[fp->cur_read]) + "/Signal";
	std::vector<float> discretized_sig;
	fp->fp->read(sig_path, discretized_sig);
	// convert to pA
	uint32_t l_sig = 0;
	float scale = s->ran/s->dig;
	for (size_t i = 0; i < discretized_sig.size(); i++) {
		float original_sig = (discretized_sig[i] + s->offset) * scale;
		if (original_sig > 30 && original_sig < 200) {
			discretized_sig[l_sig] = original_sig;
			++l_sig;
		}
	}

	s->sig = (float*)calloc(l_sig, sizeof(float));
	s->l_sig = l_sig;
	std::copy(discretized_sig.begin(), discretized_sig.begin() + l_sig, s->sig);
	fp->cur_read++;
}

#include "../include/solution.hpp"

SupplyStacks::SupplyStacks(const std::string fileName, CRATE_MOVER_MODEL crateMoverModel) : fileName_(fileName) {
  crateMoverModel_ = crateMoverModel;
  int stackCount = determineStackCount();
  initializeStacks(stackCount);
}

int SupplyStacks::determineStackCount() {
  std::ifstream File(fileName_, std::fstream::in);
  char *pLineChar = nullptr;
  size_t stackCountStart = 0;
  int stackIndex = 0;
  std::stringstream countStream;
  std::string nextCount = " 1 ";

  for(std::string line; std::getline(File, line);) {
    stackCountStart = line.find(nextCount);

    while(stackCountStart != std::string::npos) {
      stackIndex++;
      countStream << " " << stackIndex << " ";
      stackCountStart = line.find(countStream.str());
      countStream.str("");
    }

    if(stackIndex > 0) {
      stackIndex--;
      break;
    }
  }

  File.close();
  return stackIndex;
}

void SupplyStacks::initializeStacks(int stackCount) {
  std::ifstream File(fileName_, std::fstream::in);
  int stackIndex = 0;

  // Parse file filling in initial positions of crate stacks
  for(std::string line; std::getline(File, line);) {
    if(line.find(" 1 ") != std::string::npos) {
      // stack def line
      break;
    } else {
      for(int lineIndex = 0; lineIndex < line.size(); lineIndex++) {
        if(isalpha(line[lineIndex])) {
          stackIndex = convertStringIndexToStackIndex(lineIndex);

          if(crateStacks_.count(stackIndex) == 0) {
            crateStacks_.insert(std::make_pair(stackIndex, std::vector<char>{line[lineIndex]}));
          } else {
            crateStacks_[stackIndex].push_back(line[lineIndex]); 
          }
        }
      }
    }
  }

  File.close();
}

int SupplyStacks::convertStringIndexToStackIndex(int stringIndex) {
  if(stringIndex == 1) {
    return stringIndex;
  }

  return ((stringIndex-1)/4)+1;
}

void SupplyStacks::move(int crateCount, int crateSource, int createDestination) {
  char crateToMove = '\0';

  switch(crateMoverModel_) {
    case CRATE_MOVER_MODEL::CM_9000:
      for(int crateIndex = 0; crateIndex < crateCount; crateIndex++) {
        crateToMove = crateStacks_[crateSource].at(0);
        crateStacks_[crateSource].erase(crateStacks_[crateSource].begin());
        crateStacks_[createDestination].insert(crateStacks_[createDestination].begin(), crateToMove);
      }
      break;
    case CRATE_MOVER_MODEL::CM_9001:
      for(int crateIndex = crateCount-1; crateIndex >= 0; crateIndex--) {
        crateToMove = crateStacks_[crateSource].at(crateIndex);
        crateStacks_[crateSource].erase(crateStacks_[crateSource].begin()+crateIndex);
        crateStacks_[createDestination].insert(crateStacks_[createDestination].begin(), crateToMove);
      }
      break;
  }

}

void SupplyStacks::performRearrangementProcedure() {
  std::ifstream File(fileName_, std::fstream::in);
  char *pLineChar = nullptr;
  int crateCount = 0;
  int crateSource = 0;
  int crateDestination = 0;

  for(std::string line; std::getline(File, line);) {
    if(line.find("move") != std::string::npos) {
      pLineChar = strcpy(new char[line.length() + 1], line.c_str());
      sscanf(pLineChar, "move %i from %i to %i", &crateCount, &crateSource, &crateDestination);
      move(crateCount, crateSource, crateDestination);
    }
  }

  File.close();
}

std::string SupplyStacks::getTallestCrates() {
  std::stringstream tallestCrates;

  for (int stackIndex = 1; stackIndex <= crateStacks_.size(); stackIndex++) {
    if(crateStacks_[stackIndex].size() != 0) {
      tallestCrates << crateStacks_[stackIndex].at(0);
    }
  }

  return tallestCrates.str();
}

// Code Aided using common development resources
void SupplyStacks::printCrateStacks() {
  // Loop through the mapping and print the keys and values
  for (auto it = crateStacks_.begin(); it != crateStacks_.end(); ++it) {
    std::cout << it->first << "(" << it->second.size() << "): ";
    for (const auto &val : it->second) {
      std::cout << val << " ";
    }
    std::cout << std::endl;
  }
}

std::string partOne(const std::string fileName) {
  std::cout << "Part 1: " << fileName << std::endl;
  SupplyStacks supplyStacks(fileName, CRATE_MOVER_MODEL::CM_9000);
  supplyStacks.performRearrangementProcedure();
  return supplyStacks.getTallestCrates();
}

std::string partTwo(const std::string fileName) {
  std::cout << "Part 2: " << fileName << std::endl;
  SupplyStacks supplyStacks(fileName, CRATE_MOVER_MODEL::CM_9001);
  supplyStacks.performRearrangementProcedure();
  return supplyStacks.getTallestCrates();
}

int main() {
  std::string examplePartOneResult = partOne("example.txt");
  std::cout << "Part One Example Result: " << examplePartOneResult << std::endl;
  assert(examplePartOneResult.compare("CMZ") == 0);

  std::string partOneResult = partOne("input.txt");
  std::cout << "Part One Input Result: " << partOneResult << std::endl;
  assert(partOneResult.compare("SVFDLGLWV") == 0);

  std::string examplePartTwoResult = partTwo("example.txt");
  std::cout << "Part Two Example Result: " << examplePartTwoResult << std::endl;
  assert(examplePartTwoResult.compare("MCD") == 0);

  std::string partTwoResult = partTwo("input.txt");
  std::cout << "Part Two Input Result: " << partTwoResult << std::endl;
  assert(partTwoResult.compare("DCVTCVPCL") == 0);

  return 0;
}

#include <CL/cl.hpp>
#include <fstream>
#include <iostream>
#include <vector>
#include <time.h>

// =================================================================
// ---------------------- Secondary Functions ----------------------
// =================================================================

cl::Device getDefaultDevice();                          // Return the first device found in this OpenCL platform.
void initializeDevice();                                // Inicialize device and compile kernel code.
void seqSumArrays(int* a, int* b, int* c, const int N); // Sequentially performs the N-dimensional operation c = a + b.
void parSumArrays(int* a, int* b, int* c, const int N); // Parallelly performs the N-dimensional operation c = a + b.
bool checkEquality(int* c1, int* c2, const int N);      // Check if the N-dimensional arrays c1 and c2 are equal.

// =================================================================
// ------------------------ Global Variables ------------------------
// =================================================================

cl::Program program;    // The program that will run on the device.    
cl::Context context;    // The context which holds the device.    
cl::Device device;      // The device where the kernel will run.

// =================================================================
// ------------------------- Main Function -------------------------
// =================================================================

int main(){

    /**
     * Create auxiliary variables.
     * */

    clock_t start, end;
    const int EXECUTIONS = 10;

    /**
     * Prepare input arrays.
     * */

    int ARRAYS_DIM = 1 << 20;
    std::vector<int> a(ARRAYS_DIM, 3);
    std::vector<int> b(ARRAYS_DIM, 5);

    /**
     * Prepare sequential and parallel outputs.
     * */

    std::vector<int> cs(ARRAYS_DIM);
    std::vector<int> cp(ARRAYS_DIM);

    /**
     * Sequentially sum arrays.
     * */

    start = clock();
    for(int i = 0; i < EXECUTIONS; i++){
        seqSumArrays(a.data(), b.data(), cs.data(), ARRAYS_DIM);
    }
    end = clock();
    double seqTime = ((double) 10e3 * (end - start)) / CLOCKS_PER_SEC / EXECUTIONS;

    /**
     * Initialize OpenCL device.
     * */

    initializeDevice();

    /**
     * Parallelly sum arrays.
     * */

    start = clock();
    for(int i = 0; i < EXECUTIONS; i++){
        parSumArrays(a.data(), b.data(), cp.data(), ARRAYS_DIM);
    }
    end = clock();
    double parTime = ((double) 10e3 * (end - start)) / CLOCKS_PER_SEC / EXECUTIONS;

    /**
     * Check if outputs are equal.
     * */

    bool equal = checkEquality(cs.data(), cp.data(), ARRAYS_DIM);

    /**
     * Print results.
     * */

    std::cout << "Status: " << (equal ? "SUCCESS!" : "FAILED!") << std::endl;
    std::cout << "Results: \n\ta[0] = " << a[0] << "\n\tb[0] = " << b[0] << "\n\tc[0] = a[0] + b[0] = " << cp[0] << std::endl;
    std::cout << "Mean execution time: \n\tSequential: " << seqTime << " ms;\n\tParallel: " << parTime << " ms." << std::endl;
    std::cout << "Performance gain: " << (100 * (seqTime - parTime) / parTime) << "\%\n";
    return 0;
}

// =================================================================
// ---------------------- Secondary Functions ----------------------
// =================================================================

/**
 * Return the first device found in this OpenCL platform.
 * */

cl::Device getDefaultDevice(){

    /**
     * Search for all the OpenCL platforms available and check
     * if there are any.
     * */

    std::vector<cl::Platform> platforms;
    cl::Platform::get(&platforms);

    if (platforms.empty()){
        std::cerr << "No platforms found!" << std::endl;
        exit(1);
    }

    /**
     * Search for all the devices on the first platform and check if
     * there are any available.
     * */

    auto platform = platforms.front();
    std::vector<cl::Device> devices;
    platform.getDevices(CL_DEVICE_TYPE_ALL, &devices);

    if (devices.empty()){
        std::cerr << "No devices found!" << std::endl;
        exit(1);
    }

    /**
     * Return the first device found.
     * */

    return devices.front();
}

/**
 * Inicialize device and compile kernel code.
 * */

void initializeDevice(){

    /**
     * Select the first available device.
     * */

    device = getDefaultDevice();

    /**
     * Read OpenCL kernel file as a string.
     * */

    std::ifstream kernel_file("array_addition.cl");
    std::string src(std::istreambuf_iterator<char>(kernel_file), (std::istreambuf_iterator<char>()));

    /**
     * Compile kernel program which will run on the device.
     * */

    cl::Program::Sources sources(1, std::make_pair(src.c_str(), src.length() + 1));
    context = cl::Context(device);
    program = cl::Program(context, sources);

    auto err = program.build();
    if(err != CL_BUILD_SUCCESS){
        std::cerr << "Error!\nBuild Status: " << program.getBuildInfo<CL_PROGRAM_BUILD_STATUS>(device) 
        << "\nBuild Log:\t " << program.getBuildInfo<CL_PROGRAM_BUILD_LOG>(device) << std::endl;
        exit(1);
    }
}

/**
 * Sequentially performs the N-dimensional operation c = a + b.
 * */

void seqSumArrays(int* a, int* b, int* c, const int N){
    for(int i = 0; i < N; i++){
        c[i] = a[i] + b[i];
    }
}

/**
 * Parallelly performs the N-dimensional operation c = a + b.
 * */

void parSumArrays(int* a, int* b, int* c, const int N){

    /**
     * Create buffers and allocate memory on the device.
     * */

    cl::Buffer aBuf(context, CL_MEM_READ_ONLY | CL_MEM_HOST_NO_ACCESS | CL_MEM_COPY_HOST_PTR, N * sizeof(int), a);
    cl::Buffer bBuf(context, CL_MEM_READ_ONLY | CL_MEM_HOST_NO_ACCESS | CL_MEM_COPY_HOST_PTR, N * sizeof(int), b);
    cl::Buffer cBuf(context, CL_MEM_WRITE_ONLY | CL_MEM_HOST_READ_ONLY, N * sizeof(int));

    /**
     * Set kernel arguments.
     * */

    cl::Kernel kernel(program, "sumArrays");
    kernel.setArg(0, aBuf);
    kernel.setArg(1, bBuf);
    kernel.setArg(2, cBuf);

    /**
     * Execute the kernel function and collect its result.
     * */

    cl::CommandQueue queue(context, device);
    queue.enqueueNDRangeKernel(kernel, cl::NullRange, cl::NDRange(N));
    queue.enqueueReadBuffer(cBuf, CL_TRUE, 0, N * sizeof(int), c);
}

/**
 * Check if the N-dimensional arrays c1 and c2 are equal.
 * */

bool checkEquality(int* c1, int* c2, const int N){
    for(int i = 0; i < N; i++){
        if(c1[i] != c2[i]){
            return false;
        }
    }
    return true;
}

