//#define AHRS_DEBUG_OUTPUT


uint32_t timestamp;

// Quaternion
float qw, qx, qy, qz;

float gravity;
float vertical_accel, vertical_velocity, altitude;
unsigned long previousMicros = 0;
const float dt = 0.01;

float MPL_PRESSURE;
float MPL_ALTI;

float LPS_PRESSURE;
float LPS_TEMP;

long dT_baro = 0;

float ACC_X = 0;
