#define PrintErro(text) MessageBoxA((HWND)0, text, "Erro", MB_OK | MB_TOPMOST)

namespace dwm_symbol {

size_t hook_offsets[symbol_num] = {0};

namespace {
PDB_NO_DISCARD static bool IsError(PDB::ErrorCode errorCode) {

    switch (errorCode) {
    case PDB::ErrorCode::Success:
        return false;

    case PDB::ErrorCode::InvalidSuperBlock:
        PrintErro("Invalid Superblock\n");
        return true;

    case PDB::ErrorCode::InvalidFreeBlockMap:
        PrintErro("Invalid free block map\n");
        return true;

    case PDB::ErrorCode::InvalidSignature:
        PrintErro("Invalid stream signature\n");
        return true;

    case PDB::ErrorCode::InvalidStreamIndex:
        PrintErro("Invalid stream index\n");
        return true;

    case PDB::ErrorCode::UnknownVersion:
        PrintErro("Unknown version\n");
        return true;
    }

    // only ErrorCode::Success means there wasn't an error, so all other paths
    // have to assume there was an error
    return true;
}

PDB_NO_DISCARD static bool HasValidDBIStreams(const PDB::RawFile &rawPdbFile, const PDB::DBIStream &dbiStream) {
    // check whether the DBI stream offers all sub-streams we need
    if (IsError(dbiStream.HasValidImageSectionStream(rawPdbFile))) {
        return false;
    }

    if (IsError(dbiStream.HasValidPublicSymbolStream(rawPdbFile))) {
        return false;
    }

    if (IsError(dbiStream.HasValidGlobalSymbolStream(rawPdbFile))) {
        return false;
    }

    if (IsError(dbiStream.HasValidSectionContributionStream(rawPdbFile))) {
        return false;
    }

    return true;
}

} // namespace
DebugInfo *GetModuleDebugInfo(HMODULE module) {
    IMAGE_DOS_HEADER *pDos = (IMAGE_DOS_HEADER *)module;
    IMAGE_NT_HEADERS *pNt  = (IMAGE_NT_HEADERS *)((CHAR *)module + pDos->e_lfanew);

    auto pDebug =
        (IMAGE_DEBUG_DIRECTORY *)(pNt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_DEBUG].VirtualAddress +
                                  (CHAR *)module);

    auto pDebugInfo = (DebugInfo *)(pDebug->AddressOfRawData + (CHAR *)module);

    return pDebugInfo;
}
DebugInfo *GetModuleDebugInfo(const char *moduleName) {
    auto image_base = GetModuleHandleA(moduleName);
    if (image_base == nullptr) {
        return nullptr;
    }
    return GetModuleDebugInfo(image_base);
}
std::string pdburl(DebugInfo *pdb_info) {
    wchar_t w_GUID[100]{0};
    if (!StringFromGUID2(pdb_info->Guid, w_GUID, 100)) {
        return {};
    }

    char   a_GUID[100]{0};
    size_t l_GUID = 0;
    if (wcstombs_s(&l_GUID, a_GUID, w_GUID, sizeof(a_GUID)) || !l_GUID) {
        return {};
    }

    std::string guid_filtered;
    for (UINT i = 0; i != l_GUID; ++i) {
        if ((a_GUID[i] >= '0' && a_GUID[i] <= '9') || (a_GUID[i] >= 'A' && a_GUID[i] <= 'F') ||
            (a_GUID[i] >= 'a' && a_GUID[i] <= 'f')) {
            guid_filtered += a_GUID[i];
        }
    }

    char age[3]{0};
    _itoa_s(pdb_info->Age, age, 10);

    std::string url = "https://msdl.microsoft.com/download/symbols/";
    url += pdb_info->PdbFileName;
    url += '/';
    url += guid_filtered;
    url += age;
    url += '/';
    url += pdb_info->PdbFileName;
    return url;
}
size_t find_sym_rva(const PDB::RawFile &rawPdbFile, const PDB::DBIStream &dbiStream, size_t symbol_hash) {

    const PDB::ImageSectionStream imageSectionStream            = dbiStream.CreateImageSectionStream(rawPdbFile);
    const PDB::ModuleInfoStream   moduleInfoStream              = dbiStream.CreateModuleInfoStream(rawPdbFile);
    const PDB::ArrayView<PDB::ModuleInfoStream::Module> modules = moduleInfoStream.GetModules();
    const PDB::PublicSymbolStream         publicSymbolStream    = dbiStream.CreatePublicSymbolStream(rawPdbFile);
    const PDB::CoalescedMSFStream         symbolRecordStream    = dbiStream.CreateSymbolRecordStream(rawPdbFile);
    const PDB::ArrayView<PDB::HashRecord> hashRecords           = publicSymbolStream.GetRecords();

    std::hash<std::string> strhash;

    for (const PDB::HashRecord &hashRecord : hashRecords) {
        const PDB::CodeView::DBI::Record *record = publicSymbolStream.GetRecord(symbolRecordStream, hashRecord);
        if ((PDB_AS_UNDERLYING(record->data.S_PUB32.flags) &
             PDB_AS_UNDERLYING(PDB::CodeView::DBI::PublicSymbolFlags::Function)) == 0u)
            continue;

        const uint32_t rva =
            imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_PUB32.section, record->data.S_PUB32.offset);
        if (rva == 0u)
            continue;

        if (record->data.S_PUB32.name) {
            if (strhash(record->data.S_PUB32.name) == symbol_hash) {
                return static_cast<size_t>(rva);
            }
        }
    }

    size_t _ret = 0;
    for (const PDB::ModuleInfoStream::Module &module : modules) {
        if (!module.HasSymbolStream()) {
            continue;
        }
        const PDB::ModuleSymbolStream moduleSymbolStream = module.CreateSymbolStream(rawPdbFile);
        moduleSymbolStream.ForEachSymbol(
            [symbol_hash, &_ret, &strhash, &imageSectionStream](const PDB::CodeView::DBI::Record *record) {
                // only grab function symbols from the module streams
                const char *name = nullptr;
                uint32_t    rva  = 0u;
                uint32_t    size = 0u;
                if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_THUNK32) {
                    if (record->data.S_THUNK32.thunk == PDB::CodeView::DBI::ThunkOrdinal::TrampolineIncremental) {
                        // we have never seen incremental linking thunks stored inside a
                        // S_THUNK32 symbol, but better safe than sorry
                        name = "ILT";
                        rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_THUNK32.section,
                                                                           record->data.S_THUNK32.offset);
                        size = 5u;
                    }
                } else if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_TRAMPOLINE) {
                    // incremental linking thunks are stored in the linker module
                    name = "ILT";
                    rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_TRAMPOLINE.thunkSection,
                                                                       record->data.S_TRAMPOLINE.thunkOffset);
                    size = 5u;
                } else if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_LPROC32) {
                    name = record->data.S_LPROC32.name;
                    rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_LPROC32.section,
                                                                       record->data.S_LPROC32.offset);
                    size = record->data.S_LPROC32.codeSize;
                } else if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_GPROC32) {
                    name = record->data.S_GPROC32.name;
                    rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_GPROC32.section,
                                                                       record->data.S_GPROC32.offset);
                    size = record->data.S_GPROC32.codeSize;
                } else if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_LPROC32_ID) {
                    name = record->data.S_LPROC32_ID.name;
                    rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_LPROC32_ID.section,
                                                                       record->data.S_LPROC32_ID.offset);
                    size = record->data.S_LPROC32_ID.codeSize;
                } else if (record->header.kind == PDB::CodeView::DBI::SymbolRecordKind::S_GPROC32_ID) {
                    name = record->data.S_GPROC32_ID.name;
                    rva  = imageSectionStream.ConvertSectionOffsetToRVA(record->data.S_GPROC32_ID.section,
                                                                       record->data.S_GPROC32_ID.offset);
                    size = record->data.S_GPROC32_ID.codeSize;
                }
                if (name) {
                    // file << name << "\n";
                    if (strhash(name) == symbol_hash) {
                        _ret = rva;
                    }
                }

                if (rva == 0u)
                    return;
            });
    }
    return _ret;
}

bool init(void *pdbFile_baseAddress) {
    // std::hash<std::string> strhash;

    if (IsError(PDB::ValidateFile(pdbFile_baseAddress))) {
        false;
    }

    const PDB::RawFile rawPdbFile = PDB::CreateRawFile(pdbFile_baseAddress);
    if (IsError(PDB::HasValidDBIStream(rawPdbFile))) {
        false;
    }

    const PDB::InfoStream infoStream(rawPdbFile);
    if (infoStream.UsesDebugFastLink()) {
        PrintErro("PDB was linked using unsupported option /DEBUG:FASTLINK\n");

        false;
    }

    const PDB::DBIStream dbiStream = PDB::CreateDBIStream(rawPdbFile);
    if (!HasValidDBIStreams(rawPdbFile, dbiStream)) {
        false;
    }

    for (size_t idx = 0; idx < symbol_num; idx++)
        hook_offsets[idx] = find_sym_rva(rawPdbFile, dbiStream, hook_symbol_hashs[idx]);

    for (size_t idx = 0; idx < symbol_num; idx++)
        if (hook_offsets[idx] == 0)
            return false;

    return true;
}

} // namespace dwm_symbol

#include <SDL2/SDL.h>
#include <GL/gl.h>

/*
Display a static triangle. 
This code serves as the base case.
Code Supported by standard GitHub tools on 06/12/25. 
*/

int main() {
    // Initialize SDL with video
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        return 1;
    }

    // Create SDL window with OpenGL context
    SDL_Window* window = SDL_CreateWindow("Static Triangle",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 500, 500, SDL_WINDOW_OPENGL);
    if (!window) {
        SDL_Quit();
        return 1;
    }

    SDL_GLContext gl_context = SDL_GL_CreateContext(window);

    // Main loop
    bool running = true;
    SDL_Event event;
    while (running) {

        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) running = false;
        }

        // OpenGL rendering
        glClearColor(0, 0, 0, 1);
        glClear(GL_COLOR_BUFFER_BIT);

        glBegin(GL_TRIANGLES);
            // top vertex 
            glColor3f(1.0, 0.0, 0.0); // Red
            glVertex2f(0.0f, 0.5f);

            // left vertex
            glColor3f(0.0, 1.0, 0.0); // Green
            glVertex2f(-0.5f, -0.5f);

            // right vertex
            glColor3f(0.0, 0.0, 1.0); // Blue
            glVertex2f(0.5f, -0.5f);
        glEnd();

        SDL_GL_SwapWindow(window);
    }

    SDL_GL_DeleteContext(gl_context);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

/*
Program     : Class definition for implementing Queue(Circular) using arrays.
Author      : © Vipin Kumar
Created on  : March 11, 2018 20:57 IST
*/

#include <iostream>
#include <cstdlib>
#include <conio.h>
#include <stdlib.h>
#define SIZE 10

using namespace std;

class Queue {
	/*
	Summary
	-------
	Create a class to implement Queue(circular) using dynamically created array.

	Extended Summary
	----------------
	This is a class definition of a Queue(Circular) which is created using a
	dynamically created array. By dynamically created array, we means that the
	array will be created when it is to be used and deleted afterwards.
	The queue will be circular in nature i.e, the `head` index will be at index
	`rear`+1.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Class definition

	Class Variables
	---------------
	queueArray	: Dynamic array, to store the queue elements.
	capacity	: Maximum capacity of the queue.
	front		: `front` points to the front element in the queue.
	rear		: `rear` points to last element in the queue.
	count		: Current size of the queue.

	Member Functions
	----------------
	Queue()		: Constructor of class Queue.
	~Queue()	: Destructor the class Queue.
	dequeue()	: void - deleting the element.
	enqueue()	: void - inserting the element.
	peek()		: int - returns front element.
	size()		: int - returns current size of the queue.
	isEmpty()	: bool - check if queue is empty.
	isFull()	: bool - check if queue is full.
	display()	: void - display the contents of queue.

	Approach
	--------
	Class definition provides data member and member functions for the 
	Queue class.
	*/

public:
	int *queueArray;							
	int capacity;								
	int front;									
	int rear;									
	int count;									

	Queue();									
	~Queue();									
	void dequeue();								
	void enqueue(int);							
	int peek();  								
	int size();									
	bool isEmpty();								
	bool isFull();								
	void display();								
};

Queue::Queue() {
	/*
	Summary
	-------
	Create a constructor for Queue class.

	Extended Summary
	----------------
	This is a constructor definition of a Queue class. This constructor
	initializes the class variables and alloted memory space for the
	them. It also creates the dynamic array. A Constructor definition
	is necessary because of it's importance in memory allotment.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Queue Constructor definition.

	Approach
	--------
	Constructor definition provides information of data member when they 
	are being initialized at run time.
	*/

	capacity = 0;
	count = 0;
	front = -1;
	rear = -1;
	queueArray = new int[SIZE];
}

Queue::~Queue() {
	/*
	Summary
	-------
	Create a destructor for Queue class.

	Extended Summary
	----------------
	This is a destructor definition of a Queue class. This destructor
	deletes the dynamically alloted variables and free the space.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Queue Destructor definition.

	Approach
	--------
	Destructor definition provides information of data member when they are
	being deleted at run time.
	*/

	delete queueArray;
}

bool Queue::isEmpty () {
	/*
	Summary
	-------
	Create isEmpty() function.

	Extended Summary
	----------------
	isEmpty function tells about the condition when the queue is empty. This condition 
	will be checked while deleting elements from the queue as we can't delete any 
	element from empty queue.

	Parameters
	----------
	None

	Returns
	-------
	true - bool value, if queue is empty.
	false - bool value, if queue is not empty.

	Description
	-----------
	isEmpty() function definition.

	Approach
	--------
	Check the value of `front` if it is -1.
	*/

	if (front == -1) {
		return true;
	}
	else {
		return false;
	}
}

bool Queue::isFull () {
	/*
	Summary
	-------
	Create isFull() function.

	Extended Summary
	----------------
	isFull function tells about the condition when the queue is full. This condition 
	will be checked while inserting elements in the queue as we can't insert any 
	element in a queue which is full.

	Parameters
	----------
	None

	Returns
	-------
	true - bool value, if queue is full.
	false - bool value, if queue is not full.

	Description
	-----------
	isFull() function definition.

	Approach
	--------
	Check the value of `rear` if it is SIZE - 1.
	*/

	if ((rear == capacity - 1 && front == 0) || (rear == front - 1)) {
		return true;
	}
	else {
		return false;
	}
}

void Queue::enqueue (int element) {
	/*
	Summary
	-------
	Create enqueue() function.

	Extended Summary
	----------------
	enqueue() function will insert the element specified by the argument. The 
	element will be added at the `rear` end of the queue. The element can be inserted 
	only when queue is not full. In case, it will prompt that queue is already full.
	With the insertion of the element at `rear` end, it will also increment the current 
	size of the queue specified by the `count` variable.


	Parameters
	----------
	element : int - the element to be inserted at the rear end of the queue.

	Returns
	-------
	None

	Description
	-----------
	enqueue() function definition.

	Approach
	--------
	The element will be added at the `rear` end of the queue. When the `rear` will be
	`capacity`-1 and front is not zero, rear is set to zero and element is inserted at 
	rear end.
	*/

	if (isFull()) {
		cerr << "ERROR: Queue is already full. Delete some elements to enter more.";
		getch ();
		return;
	}

	// First element.
	else if (front == -1) {
		front = 0;
		rear = 0;
		queueArray[rear] = element;
		count++;
	}

	else if (rear == capacity - 1 && front != 0) {
			rear = 0;
			queueArray[rear] = element;
			count++;

	}

	else {
		rear++;
		queueArray[rear] = element;
		count++;
	}
}

void Queue::dequeue() {
	/*
	Summary
	-------
	Create dequeue() function.

	Extended Summary
	----------------
	dequeue() function will delete the element. The element at the `front` will be 
	deleted from the queue. The element can be deleted only when queue is not empty. 
	In case, it will prompt that queue is empty. With the deletion of the element from 
	`front`, it will also decrement the current size of the queue specified by the 
	`count` variable.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	dequeue() function definition.

	Approach
	--------
	The element will be deleted from the `front` size of the queue when queue is not empty. 
	When the `front` will be equal to `rear`, front will be set to -1, case of single element.
	In rest cases, front will be incremented, in case of front =  capacity - 1, front will be 
	incremented and due to circular nature of queue, it will be 0.
	*/

	if (isEmpty()) {
		cerr << "ERROR: Queue is empty. Insert some elements to delete.\n";
		getch ();
		return;
	}

	// In case of single element.
	else if (front == rear) {
		front = -1;
		rear = -1;
		count--;
	} 

	else if (front == capacity - 1) {
		front = 0;
		count--;
	}

	else {
		front++;
		count--;
	}
}

int Queue::peek () {
	/*
	Summary
	-------
	Create peek() function.

	Extended Summary
	----------------
	peek() function will gives the element present at front of queue, until the queue
	is not empty.In case of queue being empty, it will prompt that queue is empty
	and thus, no front element is there.

	Parameters
	----------
	None

	Returns
	-------
	queueArray[front] : int - front element of the queue.

	Description
	-----------
	peek() function definition.

	Approach
	--------
	Return queueArray[front] whenever queue is not empty.
	*/

	if (!isEmpty()) {
		return queueArray[front];
	}
	else {
		cout << "Queue is empty. No front element.\n";
		return -1;
	}

}

int Queue::size () {
	/*
	Summary
	-------
	Create size() function.

	Extended Summary
	----------------
	size() function will gives the current size of the queue. The current size will
	always be less than or equal to `capacity` of the queue.

	Parameters
	----------
	None

	Returns
	-------
	count : int - current size of the queue.

	Description
	-----------
	size() function definition.

	Approach
	--------
	Return value of `count` variable.
	*/

	return count;
}

void Queue::display () {
	/*
	Summary
	-------
	Create display() function.

	Extended Summary
	----------------
	display() function will display the content of queue i.e, the status of queue. Since, it
	is circular queue, some checks are required in order to get the exact status of the queue.
	When `rear` is ahead of `front`, we simply print queue from `front` to `rear`. In case when
	`front` is ahead of `rear`, we will be needed to print the queue in two parts - from `front`
	to `count` and from 0 to `rear`.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	display() function definition.

	Approach
	--------
	cout the content of array specified by queueArray varuable.
	*/

	if (isEmpty()) {
		cout << "Queue is Empty.";
		return;
	}

	cout << "Queue is ";
	if (rear >= front) {
		for (int i = front;  i <= rear;  i++) {
			cout << queueArray[i] << " ";
		}
	}

	else {
		for (int i = front; i < count; i++) {
			cout << queueArray[i] << " ";
		}

		for (int i = 0; i <= rear; i++) {
			cout << queueArray[i] << " ";
		}
	}
}

int main () {
	/*
	Summary
	-------
	Create main() function.

	Extended Summary
	----------------
	main() function will invoke all the member function defined under class Queue 
	according to their need and usability with the help of object of class.

	Parameters
	----------
	None

	Returns
	-------
	0 : int - succesful termination of program.

	Description
	-----------
	main() function definition.

	Approach
	--------
	Switch cases are used to different functionalities under class Queue.
	*/

	// Object of class Queue.
	Queue q;

	int choice;
	int element;
	int peekElement;
	int currentSize;

	system ("cls");
	cout << "\t\t***** CIRCULAR QUEUE USING ARRAY\n\n";
	cout << "Enter the capacity of queue: ";
	cin >> q.capacity;

	q.queueArray = new int[q.capacity];

	// Menu driven.
	while (true) {
		system("cls");
		cout << "\t\t***** CIRCULAR QUEUE USING ARRAY\n\n";
		cout << "1. ENQUEUE\n";
		cout << "2. DEQUEUE\n";
		cout << "3. FRONT ELEMENT\n";
		cout << "4. SIZE\n";
		cout << "5. DISPLAY\n";
		cout << "6. EXIT\n";

		cout << "Enter the choice: ";
		cin >> choice;

		switch (choice) {

		// Enqueue an `element`.
		case 1: cout << "Enter the element: ";
				cin >> element;
				q.enqueue (element);
				q.display ();
				getch ();
				break;

		// Dequeue from the front of queue.
		case 2: q.dequeue ();
				q.display ();
				getch ();
				break;

		// Front element of queue. 
		case 3: peekElement = q.peek ();
				if (!q.isEmpty()) {
					cout << "Front element is " << peekElement;
				}
				getch ();
				break;

		// Current size of queue.
		case 4: currentSize = q.size ();
				cout << "Current size of queue is " << currentSize;
				getch ();
				break;

		// Display content of queue i.e, current status.
		case 5: q.display ();
				getch ();
				break;

		// Exit from the program.
		case 6: exit (0);
				break;

		// Wrong Choice entered.
		default:
			cerr << "ERROR: Invalid Choice, re-enter your choice.\n";
			getch ();
			break;
		}
	}
	getch();
	return 0;
}

