// Function prototype for the Window Procedure
LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);

// Function to create and show a simple window
HWND CreateSimpleWindow(const char* title) {
    // Register the window class
    const char CLASS_NAME[] = "Simple Window Class";
    WNDCLASS wc = {};

    wc.lpfnWndProc = WindowProc;
    wc.hInstance = GetModuleHandle(NULL);
    wc.lpszClassName = CLASS_NAME;

    RegisterClass(&wc);

    // Create the window
    HWND hwnd = CreateWindowEx(
        0,                              // Optional window styles
        CLASS_NAME,                     // Window class
        title,                          // Window text
        WS_OVERLAPPEDWINDOW,            // Window style

        // Size and position
        CW_USEDEFAULT, CW_USEDEFAULT, 200, 100,

        NULL,       // Parent window
        NULL,       // Menu
        wc.hInstance,  // Instance handle
        NULL        // Additional application data
    );

    ShowWindow(hwnd, SW_SHOW);

    return hwnd;
}

// Window procedure function
LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }

    return DefWindowProc(hwnd, uMsg, wParam, lParam);
}

char* GetLastErrorAsString() {
    // Retrieve the last error code
    DWORD errorMessageID = ::GetLastError();
    if(errorMessageID == 0) {
        // No error message has been recorded
        return strdup("No error");
    }

    LPSTR messageBuffer = nullptr;
    size_t size = FormatMessageA(
        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr,
        errorMessageID,
        MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
        (LPSTR)&messageBuffer,
        0, nullptr);

    // Copy the error message into a std::string
    std::string message(messageBuffer, size);

    // Free the buffer allocated by the system
    LocalFree(messageBuffer);

    // Return a copy of the string as a char*
    return strdup(message.c_str());
}

#include "UnitLoopInfo.h"

#include <stack>

using namespace llvm;
using namespace cs426;

void UnitLoopInfo::addLoop(BasicBlock *header, const std::set<BasicBlock *> &blocks, DominatorTree &DT) {
    if (this->Loops.find(header) == Loops.end()) { // Loop isn't stored
        std::set<BasicBlock *> exitBlocks;
        for (auto *BB : blocks) {
            for (auto *Succ : successors(BB)) {
                if (blocks.find(Succ) == blocks.end()) {
                    exitBlocks.insert(Succ);
                }
            }
        }

        // Compute the preheader
        BasicBlock *preheader = nullptr;
        for (auto *Pred : predecessors(header)) {
            if (blocks.find(Pred) == blocks.end()) {
                if (preheader) {
                    // Multiple predecessors outside the loop; cannot determine preheader
                    preheader = nullptr;
                    break;
                } else {
                    preheader = Pred;
                }
            }
        }

        this->Loops[header] = {
            header,
            preheader,
            blocks,
            exitBlocks
        };
    }
}

const std::map<BasicBlock *, UnitLoopInfo::Loop> & UnitLoopInfo::getLoops() const {
	return this->Loops;
}

const UnitLoopInfo::Loop *UnitLoopInfo::getLoopForHeader(BasicBlock *header) {
	if(this->Loops.find(header) == this->Loops.end()) {
		return nullptr;
	} 
	return &(this->Loops[header]);
}

