  STORAGE,
  WIFI, 
  UNIT,
  OFFSET
};
const int NUM_MENUS = 6;

bool menuActive = false;
bool liveCapture = true;
bool manualCapture = false;
bool showRecord = false;
bool captureActive = false;

bool useMeters = false;
bool applyOffset = false;
