bool edgegdi::init()
{
    auto gdi32 = (uintptr_t)GetModuleHandleA("gdi32.dll");
    if (!gdi32)
        return false;

    /*
    48 89 05 ?? ?? ?? ?? E9 ?? ?? ?? ??
    \x48\x89\x05\x00\x00\x00\x00\xE9\x00\x00\x00\x00, xxx????x????
    */
    g_pEdgeGdi = FindPattern(gdi32, 0xFF000, "\x48\x89\x05\x00\x00\x00\x00\xE9\x00\x00\x00\x00", "xxx????x????", 0);
    if (g_pEdgeGdi)
    {
        uint32_t offset = *(uint32_t*)(g_pEdgeGdi + 3);
        g_pEdgeGdi = g_pEdgeGdi + 7 + offset;
    }
    printf("g_pEdgeGdi: 0x%p\n", g_pEdgeGdi);
    return g_pEdgeGdi != NULL;
}

bool edgegdi::hook(uintptr_t BitBltHook)
{
    auto win32u = GetModuleHandleA("win32u.dll");
    auto gdi32 = GetModuleHandleA("gdi32.dll");
    auto gdi32full = GetModuleHandleA("gdi32full.dll");
    auto ntdll = GetModuleHandleA("ntdll.dll");
    if (!gdi32full || !gdi32 || !win32u || !ntdll)
        return false;

    //
    // Initialize orig functions
    BitBltOrig = (BitBlt_t)GetProcAddress(gdi32full, "BitBlt");
    CreateDIBSectionOrig = (CreateDIBSection_t)GetProcAddress(gdi32full, "CreateDIBSection");
    CreateFontWOrig = (CreateFontW_t)GetProcAddress(gdi32full, "CreateFontW");
    CreateFontIndirectWOrig = (CreateFontIndirectW_t)GetProcAddress(gdi32full, "CreateFontIndirectW");
    CreateCompatibleDCOrig = (CreateCompatibleDC_t)GetProcAddress(gdi32full, "CreateCompatibleDC");
    CreateDCWOrig = (CreateDCW_t)GetProcAddress(gdi32, "bCreateDCW");
    CreateICWOrig = (CreateICW_t)CreateDCWOrig;
    InternalDeleteDCOrig = (InternalDeleteDC_t)GetProcAddress(gdi32, "InternalDeleteDC");
    InternalDeleteObjectOrig = (InternalDeleteObject_t)GetProcAddress(gdi32, "InternalDeleteObject");
    GetObjectTypeOrig = (GetObjectType_t)GetProcAddress(gdi32full, "GetObjectType");
    GetObjectWOrig = (GetObjectW_t)GetProcAddress(gdi32full, "GetObjectW");
    GetStockObjectOrig = (GetStockObject_t)GetProcAddress(gdi32full, "GetStockObject");
    GetTextMetricsWOrig = (GetTextMetricsW_t)GetProcAddress(gdi32full, "GetTextMetricsW");
    GetTextExtentPoint32WOrig = (GetTextExtentPoint32W_t)GetProcAddress(gdi32full, "GetTextExtentPoint32W");
    SelectClipRgnOrig = (SelectClipRgn_t)GetProcAddress(gdi32full, "SelectClipRgnImpl");
    SelectObjectOrig = (SelectObject_t)GetProcAddress(gdi32full, "SelectObjectImpl");
    SetMapModeOrig = (SetMapMode_t)GetProcAddress(gdi32full, "SetMapMode");
    D3DKMTOpenAdapterFromHdcOrig = (D3DKMTOpenAdapterFromHdc_t)GetProcAddress(win32u, "NtGdiDdDDIOpenAdapterFromHdc");
    ExtCreateRegionOrig = (ExtCreateRegion_t)GetProcAddress(gdi32full, "NtGdiExtCreateRegion");

    //
    // Initialize own_table
    own_table[0] = (uintptr_t)BitBltHook/*BitBltOrig*/;
    own_table[1] = (uintptr_t)CreateDIBSectionOrig;
    own_table[2] = (uintptr_t)CreateFontWOrig;
    own_table[3] = (uintptr_t)CreateFontIndirectWOrig;
    own_table[4] = (uintptr_t)CreateCompatibleDCOrig;
    own_table[5] = (uintptr_t)CreateDCWOrig;
    own_table[6] = (uintptr_t)CreateICWOrig;
    own_table[9] = (uintptr_t)InternalDeleteDCOrig;
    own_table[11] = (uintptr_t)InternalDeleteObjectOrig;
    own_table[12] = (uintptr_t)GetObjectTypeOrig;
    own_table[13] = (uintptr_t)GetObjectWOrig;
    own_table[14] = (uintptr_t)GetStockObjectOrig;
    own_table[15] = (uintptr_t)GetTextMetricsWOrig;
    own_table[16] = (uintptr_t)GetTextExtentPoint32WOrig;
    own_table[17] = (uintptr_t)SelectClipRgnOrig;
    own_table[18] = (uintptr_t)SelectObjectOrig;
    own_table[19] = (uintptr_t)SetMapModeOrig;
    own_table[22] = (uintptr_t)D3DKMTOpenAdapterFromHdcOrig;
    own_table[23] = (uintptr_t)NotImplemented;
    own_table[24] = (uintptr_t)NotImplemented;


    // Replace vtable ptr
    DWORD OldProtect;
    VirtualProtect((LPVOID)g_pEdgeGdi, sizeof(uintptr_t), PAGE_READWRITE, &OldProtect);
    *(uintptr_t**)g_pEdgeGdi = own_table;
    VirtualProtect((LPVOID)g_pEdgeGdi, sizeof(uintptr_t), OldProtect, &OldProtect);

    return true;
}

#include <iostream>
#include <iomanip>
#include <random>
#include <ctime>

#include "root_finder/root_finder.hpp"
#include "JenkinsTraub/jt.h"

using namespace std;
using namespace Eigen;

// Use Mersenne Twister as PRNG
std::mt19937_64 gen;
std::uniform_real_distribution<double> uniformReal(0.0, 1.0);

void testRootFinder(int order)
{
    int numRounds = 300000;
    double tol = 1e-8;
    int dispPrecision = 12;

    // Randomly geenrate polynomial whose all real roots lie in an interval
    set<double> realRoots;
    VectorXd coeffs(1);
    coeffs << 1;
    double tempRoot;
    for (int i = 1; i <= order; i++)
    {
        VectorXd b(2);
        tempRoot = (uniformReal(gen) - 0.5) * 10000;
        b << 1, -tempRoot;
        coeffs = RootFinder::polyConv(coeffs, b);
        realRoots.insert(tempRoot);
    }

    // Show ground truth
    cout << "------------------ Benchmark Companion Matrix Method, Roots Isolation Method, and Jenkins-Traub Algorithm ------------------" << endl;

    cout << "Ground Truth: " << endl;
    for (auto it = realRoots.begin(); it != realRoots.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;

    // Running root finder for multiple rounds
    set<double> rts1, rts2, rts3;
    VectorXd coeffsReversed = coeffs.reverse();
    VectorXcd rts3Vec;
    clock_t ini = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by eigen values of companion matrix
        rts1 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol, false);
    }
    clock_t mid1 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by real roots isolation, i.e., in (-inf, inf)
        rts2 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol);
    }
    clock_t mid2 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by Jenkins-Traub algorithm
        jt::findRootsJenkinsTraub(coeffsReversed, &rts3Vec);
    }
    clock_t fin = clock();

    // Results
    cout << "Average Execution Time for Companion Matrix Method: " << endl
         << (mid1 - ini) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Real Roots Isolation Method: " << endl
         << (mid2 - mid1) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Jenkins-Traub Algorithm: " << endl
         << (fin - mid2) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Roots Found by Companion Matrix Method: " << endl;
    for (auto it = rts1.begin(); it != rts1.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Real Roots Isolation Method: " << endl;
    for (auto it = rts2.begin(); it != rts2.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Jenkins-Traub Algorithm: " << endl;
    for (int i = 0; i < rts3Vec.size(); i++)
    {
        if (rts3Vec(i).imag() < tol)
        {
            rts3.insert(rts3Vec(i).real());
        }
    }
    for (auto it = rts3.begin(); it != rts3.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
}

int main(int argc, char **argv)
{

    testRootFinder(8);

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define big 1000000000000000

typedef long long ll;
typedef long double ld;

// Supported via standard GitHub programming aids
struct fraction {
    ll num, den;

    fraction(ll num = 0, ll den = 1) : num(num), den(den) {
        ll g = __gcd(num, den);
        num /= g;
        den /= g;
        if (den < 0) {
            num = -num;
            den = -den;
        }
    }

    fraction reduce() const {
        ll g = __gcd(num, den);
        ll tmpNum = num / g;
        ll tmpDen = den / g;
        if (tmpDen < 0) {
            tmpNum = -tmpNum;
            tmpDen = -tmpDen;
        }
        return {tmpNum, tmpDen};
    }

    fraction operator+(const fraction &f) const {
        return {num * f.den + f.num * den, den * f.den};
    }

    fraction operator-(const fraction &f) const {
        return {num * f.den - f.num * den, den * f.den};
    }

    fraction operator*(const fraction &f) const {
        return {num * f.num, den * f.den};
    }

    fraction operator/(const fraction &f) const {
        return {num * f.den, den * f.num};
    }

    bool operator<(const fraction &f) const {
        return num * f.den < f.num * den;
    }

    bool operator==(const fraction &f) const {
        return num * f.den == f.num * den;
    }

    bool operator>(const fraction &f) const {
        return num * f.den > f.num * den;
    }

    bool operator<=(const fraction &f) const {
        return num * f.den <= f.num * den;
    }

    bool operator>=(const fraction &f) const {
        return num * f.den >= f.num * den;
    }

    friend ostream &operator<<(ostream &os, const fraction &f) {
        os << f.num;
        if (f.den != 1) {
            os << "/" << f.den;
        }
        return os;
    }
};

const int MAX_N = 2;                             // adjust as needed
struct AugmentedMatrix {
    fraction mat[MAX_N][MAX_N + 1];
};
struct ColumnVector {
    fraction vec[MAX_N];
};

ColumnVector GaussianElimination(int N, AugmentedMatrix Aug) {
    // check if any eqn is invalid
    for (int i = 0; i < N; ++i) {
        bool valid = false;
        for (int j = 0; j < N; ++j) {
            if (Aug.mat[i][j].num != 0) {
                valid = true;
                break;
            }
        }
        if (!valid && Aug.mat[i][N].num != 0) {
            ColumnVector Ans;
            Ans.vec[0].num = big;
            Ans.vec[0].den = big;
            Ans.vec[1].num = big;
            Ans.vec[1].den = big;
            return Ans;
        }
    }
    // check linearly dependent
    bool dep = true;
    for (int i = 0; i < 3; ++i) {
        if ((Aug.mat[0][i].num == 0) != (Aug.mat[1][i].num == 0)) {
            dep = false; // 1 has number 1 doesn't, sure not dependent
            break;
        }
    }
    if (dep) { // maybe dependent
        vector<fraction> ratios;
        for (int i = 0; i < 3; ++i) {
            if (Aug.mat[0][i].num != 0) {
                ratios.push_back(Aug.mat[1][i] / Aug.mat[0][i]);
            }
        }
        bool same = true;
        for (int i = 1; i < ratios.size(); ++i) {
            if (ratios[i] != ratios[i - 1]) {
                same = false;
                break;
            }
        }
        if (same && ratios.size() == 3) {
            ColumnVector Ans;
            Ans.vec[0].num = big;
            Ans.vec[0].den = big;
            Ans.vec[1].num = big;
            Ans.vec[1].den = big;
            return Ans;
        }
    }
    // check if any equation has only 1 variable, then we can solve directly
    for (int i = 0; i < N; ++i) { // which eqn
        int eqn[2] = {0, 0};
        for (int j = 0; j < N; ++j) { // which variable
            if (Aug.mat[i][j].num != 0) eqn[j] = 1;
        }
        if (eqn[0] + eqn[1] == 1) {
            int varIdx = eqn[0] == 1 ? 0 : 1;
            int varIdxOther = eqn[0] == 1 ? 1 : 0;
            int eqnIdx = i;
            int eqnIdxOther = !i;
            ColumnVector Ans;
            Ans.vec[varIdx] = Aug.mat[i][N] / Aug.mat[i][varIdx];
            // sub this to other eqn
            if (Aug.mat[eqnIdxOther][varIdxOther] == 0) {
                Ans.vec[varIdxOther].num = big;
                Ans.vec[varIdxOther].den = big;
                // check if consistent with first eqn too
                if (Aug.mat[eqnIdxOther][varIdx] * Ans.vec[varIdx] != Aug.mat[eqnIdxOther][N]) {
                    Ans.vec[varIdx].num = big;
                    Ans.vec[varIdx].den = big;
                }
            } else {
                Ans.vec[varIdxOther] = (Aug.mat[eqnIdxOther][N] - Aug.mat[eqnIdxOther][varIdx] * Ans.vec[varIdx]) /
                                       Aug.mat[eqnIdxOther][varIdxOther];
            }
            return Ans;
        }
    }


    // normal case
    // input: N, Augmented Matrix Aug, output: Column vector X, the answer
    for (int i = 0; i < N - 1; ++i) {                // forward elimination
        for (int j = i + 1; j < N; ++j) {               // actual fwd elimination
            for (int k = N; k >= i; --k) {
                if (Aug.mat[i][i].num == 0) { // mark invalid
                    Aug.mat[i][i].num = big;
                    Aug.mat[i][i].den = big;
                } else Aug.mat[j][k] = Aug.mat[j][k] - Aug.mat[i][k] * Aug.mat[j][i] / Aug.mat[i][i];
            }
        }
    }

    ColumnVector Ans;                              // back substitution phase
    for (int j = N - 1; j >= 0; --j) {               // start from back
        fraction t = 0;
        for (int k = j + 1; k < N; ++k)
            t = t + Aug.mat[j][k] * Ans.vec[k];
        if ((Aug.mat[j][j].num) == 0) { // mark invalid
            Ans.vec[j].num = big;
            Ans.vec[j].den = big;
        } else Ans.vec[j] = (Aug.mat[j][N] - t) / Aug.mat[j][j]; // the answer is here
    }
    return Ans;
}

AugmentedMatrix update(AugmentedMatrix Aug, string s, int idx) {
    bool plus = true, lhs = true;
    int x = 0, y = 0, constant = 0;
    for (int i = 0; i < s.size(); ++i) {
        if (s[i] == '=') {
            lhs = false;
            plus = true;
        }
        if (s[i] == '-' && s[i + 1] == ' ') plus = false;
        if (s[i] == '+') plus = true;
        if (isdigit(s[i]) || s[i] == 'x' || s[i] == 'y') {
            if (i != 0 && s[i - 1] == '-') plus = !plus;
            string digCurr;
            while (isdigit(s[i])) digCurr += s[i++];
            if (s[i] == 'x') {
                if (digCurr.empty()) digCurr = "1";
                if (lhs) x += (plus ? 1 : -1) * stoi(digCurr);
                else x -= (plus ? 1 : -1) * stoi(digCurr);
            } else if (s[i] == 'y') {
                if (digCurr.empty()) digCurr = "1";
                if (lhs) y += (plus ? 1 : -1) * stoi(digCurr);
                else y -= (plus ? 1 : -1) * stoi(digCurr);
            } else {
                if (lhs) constant += (plus ? 1 : -1) * stoi(digCurr);
                else constant -= (plus ? 1 : -1) * stoi(digCurr);
            }
        }
    }
    Aug.mat[idx][0] = fraction(x);
    Aug.mat[idx][1] = fraction(y);
    Aug.mat[idx][2] = fraction(-constant);
    return Aug;
}

