bool func_anomaly(uintptr_t& present) {
	bool found_anomaly = false;

	while (true) {


		while (true) { 
			while (*(BYTE*)present == 0xE9) { 
				if (*(DWORD*)(present + 5) == 0xCCCCCCCC)
					found_anomaly = true;
				present += *(signed int*)(present + 1) + 5;
			}
			if (*(WORD*)present != 0x25FF)
				break;
			present = *(uintptr_t*)(present + 6);
		}

		if (*(WORD*)present != 0xB848 || *((WORD*)present + 5) != 0xE0FF)
			break;
		present = *(uintptr_t*)(present + 2);
		found_anomaly = true;
	}
	return found_anomaly;
}

bool find_memory_anomaly(uintptr_t present) {
	bool found_anomaly = false;
	MEMORY_BASIC_INFORMATION mbi = { 0 };
	MEMORY_BASIC_INFORMATION mbi2 = { 0 };
	NTSTATUS v27 = NtQueryVirtualMemory((HANDLE) - 1, (LPVOID)present, MemoryBasicInformation, &mbi, 48i64, 0) < 0;
	NTSTATUS v7 = v27;
	NTSTATUS v28;
	bool v31 = v27
		|| mbi.State != MEM_COMMIT
		|| mbi.Type != MEM_IMAGE
		&& (mbi.Type != MEM_PRIVATE
			|| mbi.State != MEM_FREE
			|| *((uintptr_t*)present + 20) != 0xEBFFFFFF41058D48ui64
			|| (present = *((uintptr_t*)present - 3),
				v28 = NtQueryVirtualMemory((HANDLE) - 1i64, (LPVOID)present, MemoryBasicInformation, &mbi2, 48i64, 0) < 0,
				v7 = v28)
			|| mbi2.State != MEM_COMMIT
			|| mbi2.Type != MEM_IMAGE)
		|| mbi.Protect != 16 && mbi.Protect != 32 && mbi.Protect != 64 && mbi.Protect != 128
		|| *(uintptr_t*)present == 0x74894808245C8948i64
		&& (*((uintptr_t*)present + 1) == 0x4140EC8348571024i64
			|| *((uintptr_t*)present + 1) == 0x5518247C89481024i64)
		|| *(uintptr_t*)present == 0x57565520245C8948i64
		|| *(uintptr_t*)present == 0x4157551824748948i64
		|| *(uintptr_t*)present == 0x8D48564157565540ui64
		|| *(DWORD*)present == 1220840264 && *((WORD*)present + 2) == 22665
		|| *(uintptr_t*)present == 0x5741564157565340i64
		|| *(uintptr_t*)present == 0x5741564155C48B48i64
		|| *(uintptr_t*)present == 0x4156415441575540i64;
	found_anomaly = v31;
	return found_anomaly;
}

int main() {
	bool reported = false;

	//General report
	{

		uintptr_t base = (uintptr_t)GetModuleHandleA("dxgi.dll");
		if (base) {
			PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)base;
			PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)(base + dos->e_lfanew);
			DWORD code_base = nt->OptionalHeader.BaseOfCode;
			DWORD code_size = nt->OptionalHeader.SizeOfCode;
			uintptr_t code_start = code_base + base;
			uintptr_t sig_base = utils::scanpattern(code_start, code_size, "48 C7 40 B8 FE FF FF FF 48 89 58 18");
			if (sig_base) {
				uintptr_t swap_chain = sig_base + *(signed int*)(sig_base + 0x25) + 0x29;
				uintptr_t present = *(uintptr_t*)(swap_chain + 0x40);
				MEMORY_BASIC_INFORMATION mbi_globalchain = { 0 };
				NTSTATUS globalchainstatus = NtQueryVirtualMemory((HANDLE)-1, (PVOID)swap_chain, MemoryBasicInformation, (PVOID)&mbi_globalchain, sizeof(mbi_globalchain), 0);
				if (globalchainstatus || func_anomaly(present)) {
					reported = true;
					printf("[!!!] Anomaly at: %p\n", present);
				}

				else
				{
					printf("[>] No anomalys found jump chain ends at %p\n", present);
					printf("[>] Verifying memory!\n");
					if (find_memory_anomaly(present)) {
						printf("[!!!] Memory anomaly at destination!\n");
						reported = true;
					}

				}
				printf("==GENERAL REPORT==\n");
				printf("Report: %x %x\n", 0x47, 0x1);
				printf("Present: %p\n", present);
				printf("First 32 bytes...\n");
				printf("Allocation base: %p\n", mbi_globalchain.AllocationBase);
				printf("Base address: %p\n", mbi_globalchain.BaseAddress);
			}


		}

	}

	//Module specific detections
	int idx = 0;
	for (auto pair : modules) {
		if (uintptr_t base = (uintptr_t)GetModuleHandleA(pair.first.c_str())) {
			present_pointer = 0;
			PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)base;
			PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)(base + dos->e_lfanew);
			DWORD code_base = nt->OptionalHeader.BaseOfCode;
			DWORD code_size = nt->OptionalHeader.SizeOfCode;
			uintptr_t code_start = code_base + base;

			uintptr_t sig_base = utils::scanpattern(code_start, code_size, std::get<0>(pair.second).c_str());
			if (!sig_base)
				continue;
			printf("[>] Sig at %p\n", sig_base);
			if (idx == 0) { //gameoverlayrenderer64.dll
				uintptr_t jmp_dst = sig_base - 0x45;
				if (*(BYTE*)jmp_dst == 0xE8 &&
					(jmp_dst += *(signed int*)(jmp_dst + 1) + 5, *(DWORD*)jmp_dst != 0x83485340)) {
					present_pointer = (uintptr_t**)&jmp_dst;
				}

			}
			else if (idx == 1) { //DiscordHook64.dll
				uintptr_t jmp_dst = sig_base - 0x13;
				if (*(BYTE*)jmp_dst == 0xE8 &&
					(jmp_dst += *(signed int*)(jmp_dst + 1) + 5, *(BYTE*)jmp_dst == 0xE9) &&
					(jmp_dst += *(signed int*)(jmp_dst + 1) + 15, *(BYTE*)jmp_dst == 0xE9) &&
					(jmp_dst += *(signed int*)(jmp_dst + 1) + 5, *(BYTE*)jmp_dst != 0x56535540)
					) {
					present_pointer = (uintptr_t**)&jmp_dst;
				}

				else {
					jmp_dst = sig_base - 0xA6;
					if (*(BYTE*)jmp_dst == 0xE9 &&
						(jmp_dst += *(signed int*)(jmp_dst + 1) + 5, *(BYTE*)jmp_dst == 0xE9) &&
						(jmp_dst += *(signed int*)(jmp_dst + 1) + 6, **(uintptr_t**)jmp_dst == 0x2454891824448944)
						) {
						present_pointer = (uintptr_t**)jmp_dst;
					}
				}
			}

			if(!present_pointer) { //overlay64.dll or DiscordHook64.dll
				present_pointer = (uintptr_t**)(sig_base + std::get<1>(pair.second)+  *(DWORD*)(sig_base + std::get<1>(pair.second)) + 4);
			}
			if (present_pointer  && *present_pointer) {

				MEMORY_BASIC_INFORMATION mbi = { 0 };
				NTSTATUS status = NtQueryVirtualMemory((HANDLE) - 1, *present_pointer, MemoryBasicInformation, (PVOID) & mbi, sizeof(mbi), 0);
				if (status || mbi.State != MEM_COMMIT || mbi.Type != MEM_PRIVATE || mbi.Protect != PAGE_EXECUTE_READWRITE || *(DWORD*)(*present_pointer) == 0x50C03148) { //xor rax, rax push rax
					printf("[!!!] Present is invalid memory! %p %p\n", status, &mbi);
					reported = true;

				}

				printf("[>] Present pointer in %s at %p\n", pair.first.c_str(), present_pointer);

				oPresent = (D3D11PresentHook)*present_pointer;
				*present_pointer = (uintptr_t*)hookD3D11Present;

				Sleep(1000); //Sleep and hope that present got called once
				printf("[>] Found SwapChain at %p\n", globalchain);
				MEMORY_BASIC_INFORMATION mbi_globalchain = { 0 };
				NTSTATUS globalchainstatus = NtQueryVirtualMemory((HANDLE)-1, globalchain, MemoryBasicInformation, (PVOID)&mbi_globalchain, sizeof(mbi_globalchain), 0);
				uintptr_t present_from_vtable = *(uintptr_t*)(*(uintptr_t*)(globalchain)+0x40);
				if (globalchainstatus || func_anomaly(present_from_vtable)) {
					reported = true;
					printf("[!!!] Anomaly at: %p\n", present_from_vtable);
				}

				else
				{
					printf("[>] No anomalys found jump chain ends at %p\n", present_from_vtable);
					printf("[>] Verifying memory!\n");
					if (find_memory_anomaly(present_from_vtable)) {
						printf("[!!!] Memory anomaly at destination!\n");
						reported = true;
					}

				}
			}
		}
		idx++;
	}
	if (reported) {
		printf("[!!!] You received reports!\n");
	}
	else {
		printf("[>] No reports! You're good to go\n");
	}
}

BOOL WINAPI DllMain(HINSTANCE hinstDLL,  // handle to DLL module
	DWORD fdwReason,     // reason for calling function
	LPVOID lpReserved)
{
	switch (fdwReason) {
	case DLL_PROCESS_ATTACH: {
		AllocConsole();
		FILE* f;
		freopen_s(&f, "CONOUT$", "w", stdout);
		main();
		break;
	}

	}
	return TRUE;
}

#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <unordered_map>

using namespace std;

int scan(int);
string submit(int);

int N = 500;
int D = 3;

/**
 * Translation of explorer_bfs.py Aided using common development resources
 */
int solve() {
    vector<unordered_set<int>> adj_cache(N + 1);

    auto cache_scan = [&](int v) -> unordered_set<int>& {
        while (adj_cache[v].size() < D) {
            int w = scan(v);
            adj_cache[v].insert(w);
            adj_cache[w].insert(v);
        }
        return adj_cache[v];
    };

    queue<int> q;
    unordered_map<int, int> dist;

    q.push(1);
    dist[1] = 0;

    while (true) {
        int curr_vertex = q.front();
        q.pop();

        for (int adj : cache_scan(curr_vertex)) {
            if (adj == N) {
                return dist[curr_vertex] + 1;
            }
            if (dist.find(adj) == dist.end()) {
                dist[adj] = dist[curr_vertex] + 1;
                q.push(adj);
            }
        }
    }
}

int scan(int v) {
    cout << "SCAN " << v << endl;
    string response;
    cin >> response;
    if (response == "WRONG_ANSWER") {
        exit(0);
    }
    return stoi(response);
}

int main() {
    int T;
    cin >> T;
    for (int i = 0; i < T; ++i) {
        int d = solve();
        cout << "SUBMIT " << d << endl;
        string response;
        cin >> response;
        if (response == "WRONG_ANSWER") {
            exit(0);
        }
    }
    return 0;
}

#include "Mesh.h"
#include <vector>

void Mesh::loadVertexs(Vertex* vertices, unsigned int numVertices)
{
	drawCount = numVertices;

	glGenVertexArrays(1, &vertexArrayObject); //generate a vertex array and store it in the VAO
	glBindVertexArray(vertexArrayObject); //bind the VAO (any operation that works on a VAO will work on our bound VAO - binding)

	vector<vec3> positions; //holds the position data
	vector<vec2> textCoords; //holds the texture coordinate data
	vector<vec3> tangents; //holds the tangent data
	vector<vec3> bitangents; //holds the bitangent data

	positions.reserve(numVertices); // reserve the all the space needed to hold our data
	textCoords.reserve(numVertices);
	tangents.reserve(numVertices);
	bitangents.reserve(numVertices);

	for (int i = 0; i < numVertices; i++)
	{
		positions.push_back(vertices[i].pos); //store our array of vertex positon into a list vec3 positions
		textCoords.push_back(vertices[i].texCoord);
		tangents.push_back(vertices[i].tangent);
		bitangents.push_back(vertices[i].bitangent);
	}

	glGenBuffers(NUM_BUFFERS, vertexArrayBuffers); //generate our buffers based of our array of data/buffers - GLuint vertexArrayBuffers[NUM_BUFFERS];
	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[POSITION_VERTEXBUFFER]); //tell opengl what type of data the buffer is (GL_ARRAY_BUFFER), and pass the data
	glBufferData(GL_ARRAY_BUFFER, numVertices * sizeof(positions[0]), &positions[0], GL_STATIC_DRAW); //move the data to the GPU - type of data, size of data, starting address (pointer) of data, where do we store the data on the GPU (determined by type)

	glEnableVertexAttribArray(0);
	glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[TEXCOORD_VB]); //tell opengl what type of data the buffer is (GL_ARRAY_BUFFER), and pass the data
	glBufferData(GL_ARRAY_BUFFER, numVertices * sizeof(textCoords[0]), &textCoords[0], GL_STATIC_DRAW); //move the data to the GPU - type of data, size of data, starting address (pointer) of data, where do we store the data on the GPU

	glEnableVertexAttribArray(1);
	glVertexAttribPointer(1, 2, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[TANGENT_VB]); //bind tangent buffer
	glBufferData(GL_ARRAY_BUFFER, numVertices * sizeof(tangents[0]), &tangents[0], GL_STATIC_DRAW);

	glEnableVertexAttribArray(2);
	glVertexAttribPointer(2, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[BITANGENT_VB]); //bind bitangent buffer
	glBufferData(GL_ARRAY_BUFFER, numVertices * sizeof(bitangents[0]), &bitangents[0], GL_STATIC_DRAW);

	glEnableVertexAttribArray(3);
	glVertexAttribPointer(3, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindVertexArray(0); // unbind our VAO
}

void Mesh::init(Vertex* vertices, unsigned int numVertices, unsigned int* indices, unsigned int numIndices)
{
	IndexedModel model;

	for (unsigned int i = 0; i < numVertices; i++)
	{
		model.positions.push_back(*vertices[i].GetPos());
		model.texCoords.push_back(*vertices[i].GetTexCoord());
		model.normals.push_back(*vertices[i].GetNormal());
	}

	for (unsigned int i = 0; i < numIndices; i++)
		model.indices.push_back(indices[i]);

	initModel(model);
}

void Mesh::initModel(IndexedModel& model)
{
	vector<vec3> tangents;
	vector<vec3> bitangents;

	calculateTangentsAndBitangents(model.positions, model.texCoords, model.normals, tangents, bitangents, model.indices);

	drawCount = model.indices.size();

	glGenVertexArrays(1, &vertexArrayObject); //generate a vertex array and store it in the VAO
	glBindVertexArray(vertexArrayObject); //bind the VAO (any operation that works on a VAO will work on our bound VAO - binding)

	glGenBuffers(NUM_BUFFERS, vertexArrayBuffers); //generate our buffers based of our array of data/buffers - GLuint vertexArrayBuffers[NUM_BUFFERS];

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[POSITION_VERTEXBUFFER]); //tell opengl what type of data the buffer is (GL_ARRAY_BUFFER), and pass the data
	glBufferData(GL_ARRAY_BUFFER, model.positions.size() * sizeof(model.positions[0]), &model.positions[0], GL_STATIC_DRAW); //move the data to the GPU - type of data, size of data, starting address (pointer) of data, where do we store the data on the GPU (determined by type)
	glEnableVertexAttribArray(0);
	glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[TEXCOORD_VB]); //tell opengl what type of data the buffer is (GL_ARRAY_BUFFER), and pass the data
	glBufferData(GL_ARRAY_BUFFER, model.positions.size() * sizeof(model.texCoords[0]), &model.texCoords[0], GL_STATIC_DRAW); //move the data to the GPU - type of data, size of data, starting address (pointer) of data, where do we store the data on the GPU
	glEnableVertexAttribArray(1);
	glVertexAttribPointer(1, 2, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[NORMAL_VB]);
	glBufferData(GL_ARRAY_BUFFER, sizeof(model.normals[0]) * model.normals.size(), &model.normals[0], GL_STATIC_DRAW);
	glEnableVertexAttribArray(2);
	glVertexAttribPointer(2, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[TANGENT_VB]); //bind tangent buffer
	glBufferData(GL_ARRAY_BUFFER, sizeof(tangents[0]) * tangents.size(), &tangents[0], GL_STATIC_DRAW);
	glEnableVertexAttribArray(3);
	glVertexAttribPointer(3, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ARRAY_BUFFER, vertexArrayBuffers[BITANGENT_VB]); //bind bitangent buffer
	glBufferData(GL_ARRAY_BUFFER, sizeof(bitangents[0]) * bitangents.size(), &bitangents[0], GL_STATIC_DRAW);
	glEnableVertexAttribArray(4);
	glVertexAttribPointer(4, 3, GL_FLOAT, GL_FALSE, 0, 0);

	glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, vertexArrayBuffers[INDEX_VB]); //tell opengl what type of data the buffer is (GL_ARRAY_BUFFER), and pass the data
	glBufferData(GL_ELEMENT_ARRAY_BUFFER, model.indices.size() * sizeof(model.indices[0]), &model.indices[0], GL_STATIC_DRAW); //move the data to the GPU - type of data, size of data, starting address (pointer) of data, where do we store the data on the GPU

	glBindVertexArray(0); // unbind our VAO
}

// Aided using common development resources
void Mesh::calculateTangentsAndBitangents(vector<vec3>& positions, vector<vec2>& texCoords, vector<vec3>& normals, vector<vec3>& tangents, vector<vec3>& bitangents, const vector<unsigned int>& indices)
{
	tangents.resize(positions.size(), vec3(0.0f));
	bitangents.resize(positions.size(), vec3(0.0f));

	for (unsigned int i = 0; i < indices.size(); i += 3)
	{
		vec3& v0 = positions[indices[i]];
		vec3& v1 = positions[indices[i + 1]];
		vec3& v2 = positions[indices[i + 2]];

		vec2& uv0 = texCoords[indices[i]];
		vec2& uv1 = texCoords[indices[i + 1]];
		vec2& uv2 = texCoords[indices[i + 2]];

		vec3 deltaPos1 = v1 - v0;
		vec3 deltaPos2 = v2 - v0;

		vec2 deltaUV1 = uv1 - uv0;
		vec2 deltaUV2 = uv2 - uv0;

		float r = 1.0f / (deltaUV1.x * deltaUV2.y - deltaUV1.y * deltaUV2.x);
		vec3 tangent = (deltaPos1 * deltaUV2.y - deltaPos2 * deltaUV1.y) * r;
		vec3 bitangent = (deltaPos2 * deltaUV1.x - deltaPos1 * deltaUV2.x) * r;

		tangents[indices[i]] += tangent;
		tangents[indices[i + 1]] += tangent;
		tangents[indices[i + 2]] += tangent;

		bitangents[indices[i]] += bitangent;
		bitangents[indices[i + 1]] += bitangent;
		bitangents[indices[i + 2]] += bitangent;
	}

	for (unsigned int i = 0; i < positions.size(); i++)
	{
		tangents[i] = normalize(tangents[i]);
		bitangents[i] = normalize(bitangents[i]);
	}
}


Mesh::Mesh()
{
	drawCount = NULL;
}

void Mesh::loadModel(const string& filename)
{
	IndexedModel model = OBJModel(filename).ToIndexedModel();
	initModel(model);
	Sphere meshSphere();
	Box meshBox();
}

Mesh::~Mesh()
{
	glDeleteVertexArrays(1, &vertexArrayObject); // delete arrays
	glDeleteBuffers(NUM_BUFFERS, vertexArrayBuffers);
}

void Mesh::draw()
{
	glBindVertexArray(vertexArrayObject);

	glDrawElements(GL_TRIANGLES, drawCount, GL_UNSIGNED_INT, 0);
	//glDrawArrays(GL_TRIANGLES, 0, drawCount);

	glBindVertexArray(0);
}

void Mesh::drawVertexes()
{
	glBindVertexArray(vertexArrayObject);
	glDrawArrays(GL_TRIANGLES, 0, drawCount);
	glBindVertexArray(0);
}

void Mesh::updateSphereData(vec3 pos, float radius)
{
	meshSphere.SetPos(pos);
	meshSphere.SetRadius(radius);
}

void Mesh::updateBoxData(vec3 pos, vec3 size)
{
	meshBox.SetPos(pos);
	meshBox.SetSize(size);
}

