#define STB_IMAGE_IMPLEMENTATION
#define STB_IMAGE_WRITE_IMPLEMENTATION
#include "stb/stb_image.h"
#include "stb/stb_image_write.h"
#include "../include/rbf.hpp"
#include <stdio.h>
#include <time.h>


class Timer {
private:
	unsigned long begTime;
public:
	void start() { begTime = clock(); }
	float elapsedTime() { return float((unsigned long)clock() - begTime) / CLOCKS_PER_SEC; }
};

int main(int argc, char*argv[])
{
	if (argc != 5)
	{
		printf("Usage:\n");
		printf("--------------------------------------------------------------------\n\n");
		printf("rbf filename_out filename_in (only support ppm images) \n");
		printf("    sigma_spatial(e.g., 0.03) sigma_range(e.g., 0.1)\n\n");
		printf("--------------------------------------------------------------------\n");
		return(-1);
	}
	else
	{
		const int n = 100;
		const char * filename_out = argv[1];
		const char * filename_in = argv[2];
		float sigma_spatial = static_cast<float>(atof(argv[3]));
		float sigma_range = static_cast<float>(atof(argv[4]));

		int width, height, channel;
		unsigned char * img = stbi_load(filename_in, &width, &height, &channel, 0);
		unsigned char * img_out = 0;
		Timer timer;

		timer.start();
		for (int i = 0; i < n; ++i)
			recursive_bf(img, img_out, sigma_spatial, sigma_range, width, height, channel);
		printf("Internal Buffer: %2.5fsecs\n", timer.elapsedTime() / n);


		float * buffer = new float[(width * height* channel + width * height
									+ width * channel + width) * 2];
		timer.start();
		for (int i = 0; i < n; ++i)
			recursive_bf(img, img_out, sigma_spatial, sigma_range, width, height, channel, buffer);
		printf("External Buffer: %2.5fsecs\n", timer.elapsedTime() / n);
		delete[] buffer;

		stbi_write_bmp(filename_out, width, height, channel, img_out);
		delete[] img;
	}
}

#include "response_parser.h"
#include <HardwareSerial.h>

// code Crafted with standard coding tools
std::string extract_json(const std::string& response)
{
  auto start_pos = response.find("{");
  if (start_pos == std::string::npos)
    return "";

  auto end_pos = response.rfind("}");
  if (end_pos == std::string::npos)
    return "";

  return response.substr(start_pos, end_pos - start_pos + 1);
}

#include "Arduino.h"
#include "NidayandHelper.h"

NidayandHelper::NidayandHelper(){
  this->_configfile = "/config.json";
  this->_mqttclientid = ("ESPClient-" + String(ESP.getChipId()));

}

boolean NidayandHelper::loadconfig(){
  File configFile = SPIFFS.open(this->_configfile, "r");
  if (!configFile) {
    Serial.println("Failed to open config file");
    return false;
  }

  size_t size = configFile.size();
  if (size > 1024) {
    Serial.println("Config file size is too large");
    return false;
  }

  // Allocate a buffer to store contents of the file.
  std::unique_ptr<char[]> buf(new char[size]);

  // We don't use String here because ArduinoJson library requires the input
  // buffer to be mutable. If you don't use ArduinoJson, you may as well
  // use configFile.readString instead.
  configFile.readBytes(buf.get(), size);

  StaticJsonBuffer<200> jsonBuffer;
  this->_config = jsonBuffer.parseObject(buf.get());

  if (!this->_config.success()) {
    Serial.println("Failed to parse config file");
    return false;
  }
  return true;
}

JsonVariant NidayandHelper::getconfig(){
  return this->_config;
}

boolean NidayandHelper::saveconfig(JsonVariant json){
  File configFile = SPIFFS.open(this->_configfile, "w");
  if (!configFile) {
    Serial.println("Failed to open config file for writing");
    return false;
  }

  json.printTo(configFile);

  Serial.println("Saved JSON to SPIFFS");
  json.printTo(Serial);
  Serial.println();
  return true;
}

String NidayandHelper::mqtt_gettopic(String type) {
  return "/raw/esp8266/" + String(ESP.getChipId()) + "/" + type;
}


void NidayandHelper::mqtt_reconnect(PubSubClient& psclient){
  return mqtt_reconnect(psclient, String(NULL), String(NULL));
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, std::list<const char*> topics){
  return mqtt_reconnect(psclient, String(NULL), String(NULL), topics);
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, String uid, String pwd){
  std::list<const char*> mylist;
  return mqtt_reconnect(psclient, uid, pwd, mylist);
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, String uid, String pwd, std::list<const char*> topics){
  // Loop until we're reconnected
  boolean mqttLogon = false;
  if (uid!=NULL and pwd != NULL){
    mqttLogon = true;
  }
  while (!psclient.connected()) {
    Serial.print("Attempting MQTT connection...");
    // Attempt to connect
    if ((mqttLogon ? psclient.connect(this->_mqttclientid.c_str(), uid.c_str(), pwd.c_str()) : psclient.connect(this->_mqttclientid.c_str()))) {
      Serial.println("connected");

      //Send register MQTT message with JSON of chipid and ip-address
      this->mqtt_publish(psclient, "/raw/esp8266/register", "{ \"id\": \"" + String(ESP.getChipId()) + "\", \"ip\":\"" + WiFi.localIP().toString() +"\"}");

      //Setup subscription
      if (!topics.empty()){
        for (const char* t : topics){
           psclient.subscribe(t);
           Serial.println("Subscribed to "+String(t));
        }
      }

    } else {
      Serial.print("failed, rc=");
      Serial.print(psclient.state());
      Serial.println(" try again in 5 seconds");
      // Wait 5 seconds before retrying
      ESP.wdtFeed();
      delay(5000);
    }
  }
  if (psclient.connected()){
    psclient.loop();
  }
}

void NidayandHelper::mqtt_publish(PubSubClient& psclient, String topic, String payload){
  Serial.println("Trying to send msg..."+topic+":"+payload);
  //Send status to MQTT bus if connected
  if (psclient.connected()) {
    psclient.publish(topic.c_str(), payload.c_str());
  } else {
    Serial.println("PubSub client is not connected...");
  }
}

void NidayandHelper::resetsettings(WiFiManager& wifim){
  SPIFFS.format();
  wifim.resetSettings();
}

//M2LAB2 - Name and Birthday Compatibility
//CSC 134
//Formed using common GitHub development resources + James Moore
//2/14/2025

/*
What i asked the AI to do: 
I asked the AI to create a write me a program that will ask the user for their first name.
then ask for their birthday in dd/mm/yyyy format. If they type the format wrong, it will 
let them know and ask them to retype it. Then it will ask for the first name of someone 
that’s close to them. followed by their birthday again making sure the formats the same. 
Then the program will take each letter of their name and find the number value example a=1 b=2 c=3 
and so on then add them all together as a variable. Then it will take the numbers from their 
birthday and add those together example 02/01/1991 will be 02 + 01 + 1991 then adds the sum 
to the sum of the sum of the name. The program will set that as a total. Then it will do the 
same thing with the other person’s name and birthday. It will then take the biggest total and 
subtract the other total to get the difference and store it as difference. it will then print 
"Your value is (total) " then print " The other persons value is ( Total ) " replacing total 
with their totals. Finally print “the closer the totals the closer the relationship is”."
*/


#include <iostream>
#include <string>
#include <cctype>
#include <cmath>

using namespace std;

int getNameValue(const string& name) {
    int value = 0;
    for (char c : name) {
        if (isalpha(c)) {
            value += tolower(c) - 'a' + 1;
        }
    }
    return value;
}

int getBirthdayValue(const string& birthday) {
    int value = 0;
    string part;
    for (char c : birthday) {
        if (isdigit(c)) {
            part += c;
        } else if (c == '/') {
            value += stoi(part);
            part.clear();
        }
    }
    if (!part.empty()) {
        value += stoi(part);
    }
    return value;
}

bool isValidDate(const string& date) {
    if (date.length() != 10) return false;
    if (date[2] != '/' || date[5] != '/') return false;
    for (int i = 0; i < date.length(); ++i) {
        if (i != 2 && i != 5 && !isdigit(date[i])) return false;
    }
    return true;
}

int main() {
    // Declare variables to store user inputs
    string firstName, closePersonName, birthday, closePersonBirthday;

    // Prompt user for their first name
    cout << "Please enter your first name: ";
    cin >> firstName;

    // Prompt user for their birthday until a valid date is entered
    while (true) {
        cout << "Please enter your birthday (dd/mm/yyyy): ";
        cin >> birthday;
        if (isValidDate(birthday)) break;
        cout << "Invalid date format. Please try again." << endl;
    }

    // Prompt user for the first name of someone close to them
    cout << "Please enter the first name of someone close to you: ";
    cin >> closePersonName;

    // Prompt user for the close person's birthday until a valid date is entered
    while (true) {
        cout << "Please enter their birthday (dd/mm/yyyy): ";
        cin >> closePersonBirthday;
        if (isValidDate(closePersonBirthday)) break;
        cout << "Invalid date format. Please try again." << endl;
    }

    // Calculate the name and birthday values for the user
    int yourNameValue = getNameValue(firstName);
    int yourBirthdayValue = getBirthdayValue(birthday);
    int yourTotal = yourNameValue + yourBirthdayValue;

    // Calculate the name and birthday values for the close person
    int closePersonNameValue = getNameValue(closePersonName);
    int closePersonBirthdayValue = getBirthdayValue(closePersonBirthday);
    int closePersonTotal = closePersonNameValue + closePersonBirthdayValue;

    // Calculate the difference between the two totals
    int difference = abs(yourTotal - closePersonTotal);

    // Output the results
    cout << "Your value is " << yourTotal << endl;
    cout << "The other person's value is " << closePersonTotal << endl;
    cout << "The difference is " << difference << endl;
    cout << "The closer the totals, the closer the realationship." << endl;

    return 0;
}
